const pickBattleDirective = (mapIdx, kind = 'trainer', pressureLevel = 0, tacticId = 'balanced') => {
  const safeMapIdx = Math.max(0, Number.isFinite(mapIdx) ? mapIdx : 0);
  if (kind === 'trainer' && safeMapIdx < 1) return null;
  const pressure = Math.max(0, Math.min(2, Number.isFinite(pressureLevel) ? pressureLevel : 0));
  const baseChance = kind === 'gym' ? 0.7 : kind === 'challenge' ? 0.55 : 0.36;
  const chance = Math.min(0.85, baseChance + pressure * 0.12 + (tacticId !== 'balanced' ? 0.08 : 0));
  if (Math.random() > chance) return null;
  const candidates = BATTLE_DIRECTIVES.filter(d => safeMapIdx + pressure >= d.minMapIdx);
  return sampleWeighted(candidates, d => {
    if (d.id === 'swift_win' && tacticId === 'sturdy') return Math.max(1, d.weight - 1);
    if (d.id === 'type_mastery' && pressure > 0) return d.weight + pressure;
    if (d.id === 'no_switch' && tacticId === 'ace_focus') return d.weight + 1;
    return d.weight;
  });
};

const getTrainerPressure = (context, partyList, winStreak = 0) => {
  const maxMapLv = Number(context?.lvl?.[1] ?? context?.lvl?.[0] ?? 0);
  if (!Number.isFinite(maxMapLv) || maxMapLv <= 0 || !Array.isArray(partyList) || partyList.length === 0) return TRAINER_PRESSURE[0];
  const topLevels = partyList
    .filter(p => p && Number.isFinite(p.level))
    .map(p => p.level)
    .sort((a, b) => b - a)
    .slice(0, 3);
  if (topLevels.length === 0) return TRAINER_PRESSURE[0];
  const topAvg = topLevels.reduce((sum, lv) => sum + lv, 0) / topLevels.length;
  const lead = topAvg - maxMapLv;
  const levelPressure = lead >= 10 ? 2 : lead >= 5 ? 1 : 0;
  const streak = Math.max(0, Number.isFinite(winStreak) ? winStreak : 0);
  const streakPressure = maxMapLv >= 40 && streak >= 18 ? 2
    : maxMapLv >= 20 && streak >= 10 ? 1
    : 0;
  return TRAINER_PRESSURE[Math.max(levelPressure, streakPressure)];
};

const pickTrainerTactic = (mapIdx, isElite, pressureLevel = 0) => {
  const safeMapIdx = Math.max(0, Number.isFinite(mapIdx) ? mapIdx : 0);
  const pressure = Math.max(0, Math.min(2, Number.isFinite(pressureLevel) ? pressureLevel : 0));
  const candidates = TRAINER_TACTICS.filter(t => safeMapIdx + pressure >= t.minMapIdx);
  return sampleWeighted(candidates, t => {
    const pressureWeight = t.id === 'balanced' ? -pressure * 2 : pressure + (pressure >= 2 && ['deep_roster', 'ace_focus'].includes(t.id) ? 1 : 0);
    return Math.max(1, t.weight + pressureWeight + (isElite && t.id !== 'balanced' ? 1 : 0));
  }) || TRAINER_TACTICS[0];
};

const applyTrainerTacticToPet = (pet, tactic, slot, count, isElite) => {
  if (!pet || !tactic) return pet;
  const isAce = slot === count - 1;
  const baseMult = isElite ? 1.1 : 1;
  const tacticMult = isAce ? (tactic.aceMult || 1) : (tactic.teamMult || 1);
  const cap = isElite ? 1.15 : 1.08;
  const mult = Math.min(cap, Math.max(1, baseMult * tacticMult));
  if (mult > 1) pet.customStatMult = Math.max(pet.customStatMult || 1, mult);
  if (tactic.berry && isAce && pet.level >= 18) {
    pet.equippedBerry = tactic.berry;
  }
  return pet;
};

const totalBerryCount = (b) => Object.values(normalizeBerriesInventory(b)).reduce((s, n) => s + (typeof n === 'number' ? n : 0), 0);
const addBerries = (berries, id, amount) => {
  const o = normalizeBerriesInventory(berries);
  o[id] = Math.max(0, (o[id] || 0) + amount);
  return o;
};

const ALL_SKILL_TMS = buildSkillTmCatalog(TMS, SKILL_DB);

const getPetJutsuNatureSet = (pet) => {
  const set = new Set();
  (pet?.moves || []).forEach((m) => {
    if (!m?.isJutsu) return;
    if (m.nature) { set.add(m.nature); return; }
    const ent = Object.entries(CHAKRA_NATURE_MAP).find(([, v]) => v.gameType === m.t);
    if (ent) set.add(ent[0]);
  });
  return set;
};

/** 双打两只出战精灵能否覆盖配方 multiset：每只精灵对同种性质最多贡献一次，不同性质可由同一只承担。 */
const matchDoubleComboNatures = (pet0, pet1, natures) => {
  if (!pet0 || !pet1 || !natures?.length) return false;
  const s0 = getPetJutsuNatureSet(pet0);
  const s1 = getPetJutsuNatureSet(pet1);
  const dfs = (idx, u0, u1) => {
    if (idx >= natures.length) return true;
    const n = natures[idx];
    if (s0.has(n) && !u0[n]) {
      if (dfs(idx + 1, { ...u0, [n]: true }, u1)) return true;
    }
    if (s1.has(n) && !u1[n]) {
      if (dfs(idx + 1, u0, { ...u1, [n]: true })) return true;
    }
    return false;
  };
  return dfs(0, {}, {});
};

/** 队伍中每名精灵至多匹配配方中的一项；同性质需不同精灵各带该性质忍术。 */
const partyMatchesComboNatures = (party, natures) => {
  if (!Array.isArray(party) || !natures?.length) return false;
  const used = new Array(party.length).fill(false);
  const dfs = (i) => {
    if (i >= natures.length) return true;
    const need = natures[i];
    for (let pi = 0; pi < party.length; pi++) {
      if (used[pi]) continue;
      if (!getPetJutsuNatureSet(party[pi]).has(need)) continue;
      used[pi] = true;
      if (dfs(i + 1)) return true;
      used[pi] = false;
    }
    return false;
  };
  return dfs(0);
};

const ninjaRankAtLeast = (playerRankId, minRank) =>
  (NINJA_ID_ORDER[playerRankId] ?? 0) >= (NINJA_ID_ORDER[minRank] ?? 0);

/** 队伍中至少 3 只精灵各持有不同代表性质忍术（用于仙法·五遁大結界） */
const partyHasThreeDistinctJutsuNaturePets = (partyArr) => {
  const team = (partyArr || []).filter(Boolean);
  if (team.length < 3) return false;
  const reps = team.map((p) => {
    const s = getPetJutsuNatureSet(p);
    if (s.size === 0) return null;
    return [...s].sort()[0];
  });
  if (reps.filter(Boolean).length < 3) return false;
  return new Set(reps.filter(Boolean)).size >= 3;
};

const isComboJutsuAvailableInDouble = (combo, { pet0, pet1, ninjaRankId, party, availableChakra, chakraCostMult = 1 }) => {
  if (!pet0 || !pet1 || pet0.currentHp <= 0 || pet1.currentHp <= 0) return false;
  const totalChakra = availableChakra ?? ((pet0.chakra || 0) + (pet1.chakra || 0));
  if (totalChakra < getEffectiveChakraCost(combo, { chakraCostMult })) return false;
  if (!ninjaRankAtLeast(ninjaRankId, combo.minRank)) return false;
  if (!matchDoubleComboNatures(pet0, pet1, combo.natures)) return false;
  if (combo.id === 'yin_yang') {
    const s0 = getPetJutsuNatureSet(pet0);
    const s1 = getPetJutsuNatureSet(pet1);
    if (!((s0.has('FIRE') && s1.has('WATER')) || (s0.has('WATER') && s1.has('FIRE')))) return false;
  }
  if (combo.id === 'all_five' && !partyHasThreeDistinctJutsuNaturePets(party)) return false;
  return true;
};

const sampleWeightedTM = (tmList, maxTier = 4) => {
  if (!tmList || tmList.length === 0) return null;
  const filtered = tmList.filter(t => (t.tier || 1) <= maxTier);
  const pool = filtered.length > 0 ? filtered : tmList;
  const tmWeightFn = (tm) => {
    const p = tm.p || 0;
    if (p === 0) return 60;
    if (p < 70) return 100;
    if (p < 100) return 50;
    if (p < 130) return 15;
    if (p < 160) return 5;
    return 2;
  };
  return sampleWeighted(pool, tmWeightFn);
};

/** 特定图鉴组合同时在场时战斗伤害/防御微量加成（与存档无关，仅本场战斗） */
const TEAM_SYNERGY_PAIRS = [[4, 5], [7, 8], [1, 2], [133, 134], [25, 26]];
const computeTeamSynergyMult = (partyPets) => {
  const ids = (partyPets || []).map(p => p?.id).filter(Boolean);
  return TEAM_SYNERGY_PAIRS.some(([a, b]) => ids.includes(a) && ids.includes(b)) ? 1.03 : 1;
};

const sampleWeightedAccessory = (allowTier5 = false, qualityBoost = 0) => {
  const maxTier = allowTier5 ? 5 : 4;
  const droppable = ACCESSORY_DB.filter(a => (a.tier || 0) <= maxTier);
  if (droppable.length === 0) return null;
  const weighted = droppable.map(acc => {
    const t = acc.tier || 1;
    let w;
    if (t === 1) w = 50;
    else if (t === 2) w = 25;
    else if (t === 3) w = 10;
    else if (t === 4) w = 3;
    else w = 1;
    return { acc, w: w / Math.pow(2, Math.max(0, qualityBoost) * (maxTier - t)) };
  });
  const total = weighted.reduce((s, x) => s + x.w, 0);
  let roll = Math.random() * total;
  for (const { acc, w } of weighted) {
    roll -= w;
    if (roll <= 0) return acc;
  }
  return weighted[weighted.length - 1].acc;
};

const getEquipEffects = (pet) => {
  if (!pet) return [];
  const effects = [];
  (pet.equips || []).forEach(equip => {
    if (!equip) return;
    const accData = typeof equip === 'string' ? ACCESSORY_DB.find(c => c.id === equip) : equip;
    if (accData && accData.effect) effects.push(accData.effect);
  });
  return effects;
};

const inferCompletedSideStories = (storyProg) => {
  return SIDE_STORY_LINES.filter(s => s.id !== 'naruto' && s.id !== 'sanguo' && storyProg > s.endIdx).map(s => s.id);
};

