    const targetIdx = b.isDouble ? (b.activeIdxs?.[_dSlot] ?? b.activeIdx) : b.activeIdx;
    const player = b.playerCombatStates?.[targetIdx];
    if (!player) return;
    // 双打时选择血最低的敌人作为目标
    let enemyIdx = b.isDouble ? (b.enemyActiveIdxs?.[0] ?? b.enemyActiveIdx) : b.enemyActiveIdx;
    if (b.isDouble && b.enemyActiveIdxs?.length > 1) {
      const e0 = b.enemyParty?.[b.enemyActiveIdxs[0]];
      const e1 = b.enemyParty?.[b.enemyActiveIdxs[1]];
      if (e0 && e1 && e0.currentHp > 0 && e1.currentHp > 0) {
        enemyIdx = e1.currentHp < e0.currentHp ? b.enemyActiveIdxs[1] : b.enemyActiveIdxs[0];
      }
    }
    const enemy = b.enemyParty?.[enemyIdx];
    if (!enemy) return;
    const moves = player.combatMoves || [];
    const playerStats = getStats(party[targetIdx] || player);
    const hpPercent = player.currentHp / Math.max(1, playerStats.maxHp);
    let bestIdx = -1, bestScore = -Infinity;
    moves.forEach((m, i) => {
      if (!canUseCombatMove(b, player, m, 'player')) return;
      let score = m.p || 0;
      if (hpPercent < 0.35 && m.effect?.healPercent) {
        score = 200;
      } else if (m.p > 0) {
        let typeMod = getTypeMod(m.t, enemy.type, b);
        const enemyType2 = enemy.secondaryType || enemy.type2;
        if (enemyType2 && enemyType2 !== enemy.type) typeMod *= getTypeMod(m.t, enemyType2, b);
        if (typeMod === 0) return;
        score *= typeMod;
        const playerType2 = player.secondaryType || player.type2;
        if (m.t === player.type || m.t === playerType2) score *= 1.5;
      } else {
        score = 1;
      }
      if (score > bestScore) { bestScore = score; bestIdx = i; }
    });
    if (bestIdx < 0) { bestIdx = 0; }
