  // 🎵 [最终优化] BGM 自动切换逻辑
  // 逻辑：只有当“目标曲目”和“当前曲目”不一样时，才切歌。否则保持播放，绝不打断。
  useEffect(() => {
    if (!audioRef.current) return;

    let targetSrc = '';

    // 1. 定义【菜单音乐组】：这三个界面都用 MENU 音乐
    // 这样在它们之间切换时，targetSrc 不变，音乐就不会断
    if (view === 'menu' || view === 'name_input' || view === 'starter_select') {
      targetSrc = BGM_SOURCES.MENU;
    } 
    // 2. 定义【地图音乐组】
    else if (view === 'world_map' || view === 'grid_map' || view === 'sect_summit') {
      targetSrc = BGM_SOURCES.MAP;
    }
    // 3. 定义【战斗音乐组】
    else if (view === 'battle') {
      if (battle && (battle.isBoss || battle.isGym || battle.isChallenge || battle.type === 'eclipse_leader' || battle.type === 'spirit_domain' || battle.type === 'world_boss' || battle.type === 'eco_crisis')) {
        targetSrc = BGM_SOURCES.BOSS;
      } else {
        targetSrc = BGM_SOURCES.BATTLE;
      }
    }

    // 4. 执行播放逻辑
    const audio = audioRef.current;

    if (isMuted) {
        audio.pause();
        return;
    }
    if (!audioUnlocked) return;
    if (targetSrc && targetSrc !== currentTrack) {
        setCurrentTrack(targetSrc);
        audio.src = targetSrc;
        audio.volume = 0.5;
        audio.loop = true;
        audio.load();
        audio.play().catch(() => {});
    } else if (targetSrc === currentTrack && audio.paused) {
        audio.play().catch(() => {});
    }

  }, [view, battle, currentTrack, isMuted, audioUnlocked]);


