    // ==========================================
  
  // [新增] 核心逻辑函数群
  // ==========================================

  // 1. 计算捕获率 (修正版：适配地图和属性 + 神兽/稀有度惩罚)
  // 注意：此函数引用组件级 battle state，非纯函数
  const calculateCatchRate = (ballType, enemy) => {
      if (ballType === 'master') return 1.0;
      const isWarBall = ballType === 'war';
      const ball = isWarBall
        ? { id: 'war', name: '国战精灵球', rate: 3.0, icon: '⚔️', desc: '捕获率3.0x（消耗国战精灵球）' }
        : BALLS[ballType];
      if (!ball) return 0.1;
      let rate = ball.rate;
      
      if (!battle) {
        const baseRate = ball.rate || 1.0;
        if (ballType === 'quick') return Math.min(0.3, baseRate * 0.25);
        return Math.min(0.6, baseRate * 0.4);
      }
      const mapInfo = MAPS.find(m => m.id === battle.mapId);
      const turnCount = battle.turnCount || 0;

      // 网纹球：水系或虫系（含副属性）
      if (ballType === 'net') {
          const eTypes = [enemy.type, enemy.type2 || enemy.secondaryType].filter(Boolean);
          if (eTypes.some(t => t === 'WATER' || t === 'BUG')) rate = 3.5;
      }
      // 黑暗球：工厂/古堡/宇宙地图（maps: factory / ghost古堡主题 / space）或 幽灵系（含副属性），与 items 描述一致
      if (ballType === 'dusk') {
          const isDarkMap = mapInfo && ['factory', 'ghost', 'space'].includes(mapInfo.type);
          const eTypes = [enemy.type, enemy.type2 || enemy.secondaryType].filter(Boolean);
          const isGhostOrDark = eTypes.some(t => t === 'GHOST' || t === 'DARK');
          if (isDarkMap || isGhostOrDark) rate = 3.5;
      }
      // 先机球：前 3 回合
      if (ballType === 'quick') {
          if (turnCount < 3) rate = 3.0;
      }
      // 计时球：回合越久越强
      if (ballType === 'timer') {
          rate = 1.0 + (turnCount * 0.3);
          if (rate > 4.0) rate = 4.0;
      }

      const maxHp = getStats(enemy).maxHp || 1;
      const hpRate = Math.max(0, Math.min(1, enemy.currentHp / maxHp));
      let baseRate = Math.max(0.01, ((1 - hpRate) * 0.8 + 0.1) * rate);

      // 稀有度惩罚：神兽/高阶精灵大幅降低捕获率
      const eid = enemy.id;
      if (FINAL_GOD_IDS && FINAL_GOD_IDS.includes(eid)) {
          baseRate *= 0.08;
      } else if (NEW_GOD_IDS && NEW_GOD_IDS.includes(eid)) {
          baseRate *= 0.12;
      } else if (LEGENDARY_POOL && LEGENDARY_POOL.includes(eid)) {
          baseRate *= 0.2;
      } else if (HIGH_TIER_POOL && HIGH_TIER_POOL.includes(eid)) {
          baseRate *= 0.4;
      }

      // 等级差惩罚：敌方等级远超我方当前出战精灵时更难抓
      const activePetForCatch = battle ? (battle.playerCombatStates?.[battle.activeIdx] || party?.[0]) : party?.[0];
      if (activePetForCatch) {
          const lvlDiff = enemy.level - (activePetForCatch.level || 1);
          if (lvlDiff > 20) baseRate *= 0.3;
          else if (lvlDiff > 10) baseRate *= 0.5;
          else if (lvlDiff > 5) baseRate *= 0.7;
      }

      // 异常状态加成：睡眠/冰冻×2，麻痹/灼伤/中毒×1.5
      if (enemy.status === 'SLP' || enemy.status === 'FRZ') baseRate *= 2.0;
      else if (enemy.status === 'PAR' || enemy.status === 'BRN' || enemy.status === 'PSN') baseRate *= 1.5;

      // 治愈球：捕获后恢复满HP（倍率已在ball.rate中计算）

      // 帮派+阵营捕获率加成
      const gangCatchBonus = getGangSkillBonus(getGangSkills(gang, getGangSkillCapBonus(kingdomWar))).catchRate || 0;
      const kwCatchBonus = kingdomWar?.faction ? (FACTIONS[kingdomWar.faction]?.bonus?.catchRate || 0) : 0;
      const relicCatchBonus = getEquippedRelicEffects(relics).catchRateBonus || 0;
      baseRate *= (1 + Math.min(gangCatchBonus + kwCatchBonus + relicCatchBonus, 55) / 100);

      // 徽章加成：每枚徽章提升2%捕获率上限
      const badgeBonus = 1 + Math.min(badges.length, 10) * 0.015;
      baseRate *= badgeBonus;

      const etype = (POKEDEX.find(p => p.id === eid) || {}).type;
      if (FINAL_GOD_IDS?.includes(eid) || etype === 'COSMIC' || etype === 'GOD') return Math.min(baseRate, 0.12 + badges.length * 0.01);
      if (NEW_GOD_IDS?.includes(eid) || LEGENDARY_POOL?.includes(eid)) return Math.min(baseRate, 0.30 + badges.length * 0.015);
      if (HIGH_TIER_POOL?.includes(eid)) return Math.min(baseRate, 0.50 + badges.length * 0.02);
      return Math.min(baseRate, 0.85);
  };

  // 2. 使用洗练药
   // 2. 使用洗练药 (旧版直接使用逻辑)
  const useRebirthPill = (petIdx) => {
    const pet = partyRef.current?.[petIdx];
    if (!pet) return;
    const cost = getSpouseRerollCost(marriageRef.current, pet, getLocalDateStr());
    const currentStock = inventoryRef.current?.misc?.rebirth_pill || 0;
    if (currentStock < cost) {
      showMapToast('📦', '洗练药不足', `库存 ${currentStock} · 需要 ${cost}`, 1500);
      return;
    }
    setConfirmModal({ title:'⚠️ 洗练确认', msg:`确定要对 ${pet.name} 使用洗练药吗？\n属性、性格将重新随机，有概率变闪光！\n消耗洗练药 x${cost}`, onOk: () => { _doRebirthPill(pet.uid); } });
    return;
  };
  const _doRebirthPill = (petUid) => {
    const lockKey = `rebirth-direct:${petUid}`;
    if (!petUid || inventoryActionLocksRef.current.has(lockKey)) return;
    inventoryActionLocksRef.current.add(lockKey);
    try {
      const currentParty = partyRef.current || [];
      const petIdx = currentParty.findIndex(pet => pet.uid === petUid);
      if (petIdx < 0) return;
      const newParty = [...currentParty];
      let pet = { ...newParty[petIdx] };
      const cost = getSpouseRerollCost(marriageRef.current, pet, getLocalDateStr());
      const currentInventory = inventoryRef.current || inventory;
      const currentStock = currentInventory.misc?.rebirth_pill || 0;
      if (currentStock < cost) {
        showMapToast('📦', '洗练药不足', `库存 ${currentStock} · 需要 ${cost}`, 1500);
        return;
      }

      const spBonuses = getSpouseBonuses();
      const ivMin = spBonuses.ivBoost || 0;
      const randIV = () => Math.floor(Math.random() * Math.max(1, 32 - ivMin)) + ivMin;
      pet.ivs = { hp: randIV(), p_atk: randIV(), p_def: randIV(), s_atk: randIV(), s_def: randIV(), spd: randIV(), crit: Math.floor(Math.random() * 10) };
      const natureKeys = Object.keys(NATURE_DB);
      pet.nature = natureKeys[Math.floor(Math.random() * natureKeys.length)];
      const wasShiny = Boolean(pet.isShiny);
      const shouldBeShiny = wasShiny || Math.random() < 0.05 * (spBonuses.shinyRate || 1);
      if (shouldBeShiny && !wasShiny) pet = promotePetToShiny(pet);
      else pet.isShiny = shouldBeShiny;
      pet.diversityRng = Math.floor(Math.random() * 9) - 4;
      pet.speedRng = Math.floor(Math.random() * 71) + 40;
      pet.currentHp = getStats(pet).maxHp;
      newParty[petIdx] = pet;
      consumeSpouseReroll(cost);

      const nextInventory = {
        ...currentInventory,
        misc: { ...(currentInventory.misc || {}), rebirth_pill: currentStock - cost },
      };
      partyRef.current = newParty;
      inventoryRef.current = nextInventory;
      flushSync(() => {
        setParty(newParty);
        setInventory(nextInventory);
      });
      showMapToast('✨', '洗练完成', `性格变为：${NATURE_DB[pet.nature]?.name || pet.nature}${pet.isShiny ? ' 🌟闪光！' : ''}`, 2500);
    } finally {
      window.setTimeout(() => inventoryActionLocksRef.current.delete(lockKey), 0);
    }
  };


  // 3. 使用技能书
  const useTM = (petIdx, tmId) => {
    const lockKey = `tm:${tmId}`;
    if (inventoryActionLocksRef.current.has(lockKey)) return;
    inventoryActionLocksRef.current.add(lockKey);
    try {
    const tm = TMS.find(t => t.id === tmId) || ALL_SKILL_TMS.find(t => t.id === tmId);
    const currentInventory = inventoryRef.current || inventory;
    if (!tm || ((currentInventory.tms || {})[tmId] || 0) <= 0) return;
    const currentParty = partyRef.current || [];
    const pet = currentParty[petIdx];
    if (!pet) return;

    const petTypes = [pet.type, pet.secondaryType].filter(Boolean);
    if (!petTypes.includes(tm.type) && tm.type !== 'NORMAL') {
        showMapToast('❌', '无法学习', `${pet.name} 不是 ${TYPES[tm.type]?.name || tm.type} 属性`, 2000);
        return;
    }
    if ((pet.moves || []).some(m => m.name === tm.name)) {
        showMapToast('⚠️', '无法学习', '已经学会了该技能', 1500);
        return;
    }

    const newMove = { name: tm.name, p: tm.p, t: tm.type, pp: tm.pp, maxPP: tm.pp, desc: tm.desc, _tmId: tmId };
    
    if ((pet.moves || []).length < 4) {
        const nextInventory = { ...currentInventory, tms: { ...(currentInventory.tms || {}), [tmId]: (currentInventory.tms[tmId] || 0) - 1 } };
        const newParty = [...currentParty];
        newParty[petIdx] = {
            ...newParty[petIdx],
            moves: [...(newParty[petIdx].moves || []), newMove]
        };
        inventoryRef.current = nextInventory;
        partyRef.current = newParty;
        flushSync(() => { setInventory(nextInventory); setParty(newParty); });
        advanceBounty('learn_tm');
        showMapToast('📖', '学会技能', `${pet.name} 学会了 [${tm.name}]`, 2000);
    } else {
        const newParty = [...currentParty];
        newParty[petIdx] = {
            ...newParty[petIdx],
            pendingLearnMove: newMove
        };
        partyRef.current = newParty;
        setParty(newParty);
        setLearningPetIdx(petIdx);
        setPendingMove(newMove);
        setView('move_forget');
    }
    } finally {
      window.setTimeout(() => inventoryActionLocksRef.current.delete(lockKey), 0);
    }
  };

  // 4. 战斗中使用药品 (消耗回合)
  const useBattleItem = async (itemKey, category) => {
    if (battle?.type === 'ultra_trial') return;
    if (!battle || (battle.phase !== 'input' && battle.phase !== 'double_input_2' && !battle.showSwitch) || battleSpecialActionLockRef.current) return;
    battleSpecialActionLockRef.current = true;
    try {
    let currentInventory = inventoryRef.current || inventory;
    const _dSlot = battle.phase === 'double_input_2' ? 1 : 0;
    const targetIdx = battle.isDouble ? (battle.activeIdxs?.[_dSlot] ?? battle.activeIdx) : battle.activeIdx;
    let workingBattle = _.cloneDeep(battle);
    const itemTargetEnemyIdx = battle.isDouble
      ? (battle.targetIdx ?? battle.enemyActiveIdxs?.find(idx => battle.enemyParty?.[idx]?.currentHp > 0) ?? battle.enemyActiveIdx)
      : battle.enemyActiveIdx;
    const p = workingBattle.playerCombatStates?.[targetIdx] || party[targetIdx];
    const pState = workingBattle.playerCombatStates?.[targetIdx];
    if (!p || !pState) return;
    let used = false;
    let grantsIntimacy = false;
    let logMsg = "";

    if (category === 'meds') {
        const item = MEDICINES[itemKey];
        if (!item || !item.type) return;
        if ((currentInventory.meds?.[itemKey] || 0) <= 0) return;

        if (item.type === 'HP') {
            if (pState.currentHp <= 0) { addLog("⚠️ 无法对濒死精灵使用恢复药！"); return; }
            const max = getStats(pState, pState.stages, pState.status).maxHp;
            if (pState.currentHp >= max) { addLog("⚠️ 体力已满，无需使用！"); return; }
            const heal = item.val === 9999 ? max : item.val;
            pState.currentHp = Math.min(max, pState.currentHp + heal);
            logMsg = `使用了 ${item.name}，恢复了体力！`;
            used = true;
        } else if (item.type === 'STATUS') {
            if (item.val === 'ALL') {
                const hasVolatileStatus = !!(pState.volatiles?.confused || pState.volatiles?.sleepTurns || pState.volatiles?.frozenTurns);
                if (!pState.status && !hasVolatileStatus) { addLog("⚠️ 没有异常状态！"); return; }
                pState.status = null;
                if (pState.volatiles) { pState.volatiles.sleepTurns = 0; pState.volatiles.confused = 0; pState.volatiles.frozenTurns = 0; }
                logMsg = `使用了 ${item.name}，状态恢复正常！`;
                used = true;
            } else {
                if (pState.status !== item.val) { addLog("⚠️ 药品对当前异常无效！"); return; }
                pState.status = null;
                if (item.val === 'SLP' && pState.volatiles) pState.volatiles.sleepTurns = 0;
                if (item.val === 'FRZ' && pState.volatiles) pState.volatiles.frozenTurns = 0;
                logMsg = `使用了 ${item.name}，治愈了异常状态!`;
                used = true;
            }
        } else if (item.type === 'PP') {
             const moves = pState.combatMoves || [];
             const lowestPP = moves.filter(m => m.pp < (m.maxPP||15)).sort((a,b) => a.pp - b.pp)[0];
             if (lowestPP) {
               lowestPP.pp = Math.min(lowestPP.maxPP||15, lowestPP.pp + (item.val || 10));
               logMsg = `使用了 ${item.name}，${lowestPP.name}的PP恢复了！`;
               used = true;
             } else {
               addLog("⚠️ 所有技能PP已满！"); return;
             }
        } else if (item.type === 'PP_ALL') {
             if ((item.val || 0) >= 99) {
               const allFull = (pState.combatMoves || []).every(m => m.pp >= (m.maxPP || 15));
               if (allFull) { addLog("⚠️ 所有技能PP已满！"); return; }
               (pState.combatMoves || []).forEach(m => { m.pp = m.maxPP || m.pp; });
             } else {
               const allFull = (pState.combatMoves || []).every(m => m.pp >= (m.maxPP || 15));
               if (allFull) { addLog("⚠️ 所有技能PP已满！"); return; }
               (pState.combatMoves || []).forEach(m => { m.pp = Math.min(m.maxPP || 15, m.pp + (item.val || 10)); });
             }
             logMsg = `使用了 ${item.name}，所有技能PP得到了恢复！`;
             used = true;
        } else if (item.type === 'FULL_RESTORE') {
            const max = getStats(pState, pState.stages, pState.status).maxHp;
            if (pState.currentHp <= 0) { addLog("⚠️ 无法对濒死精灵使用！"); return; }
            const hasMissingPp = (pState.combatMoves || []).some(m => m.pp < (m.maxPP || 15));
            if (pState.currentHp >= max && !pState.status && !(item.id === 'max_elixir' && hasMissingPp)) {
              addLog("⚠️ 体力与状态已经恢复，无需使用！"); return;
            }
            pState.currentHp = max;
            pState.status = null;
            if (pState.volatiles) { pState.volatiles.sleepTurns = 0; pState.volatiles.confused = 0; }
            if (item.id === 'max_elixir') {
              (pState.combatMoves || []).forEach(m => { m.pp = m.maxPP || m.pp; });
              logMsg = `使用了 ${item.name}，体力、异常与PP全满！`;
            } else {
              logMsg = `使用了 ${item.name}，体力与状态全满！`;
            }
            used = true;
        } else if (item.type === 'REVIVE_ALL') {
            addLog("⚠️ 圣灰仅可在战斗外使用！"); return;
        } else if (item.type === 'BUFF') {
            if (!pState.stages) pState.stages = { ...DEFAULT_BATTLE_STAGES };
            const map = STAT_BUFF_MAP;
            if (item.val === 'GUARD') {
              pState.mistTurns = Math.max(pState.mistTurns || 0, 5);
              logMsg = `使用了 ${item.name}，5回合内能力不会被降低！`;
            } else if (map[item.val]) {
              const k = map[item.val];
              pState.stages[k] = Math.min(6, (pState.stages[k] || 0) + 1);
              logMsg = `使用了 ${item.name}，${item.name}生效了！`;
            } else if (item.val === 'CRIT') {
              pState.stages.crit = Math.min(6, (pState.stages.crit || 0) + 2);
              logMsg = `使用了 ${item.name}，容易击中要害！`;
            } else { addLog("⚠️ 无法使用该道具"); return; }
            used = true;
        } else if (item.type === 'REVIVE') {
             const forcedIdx = workingBattle.showSwitch && pState.currentHp <= 0 ? targetIdx : -1;
             const faintedIdx = forcedIdx >= 0 ? forcedIdx : workingBattle.playerCombatStates?.findIndex(cs => cs.currentHp <= 0);
             if (faintedIdx >= 0 && faintedIdx < workingBattle.playerCombatStates.length) {
               const faintedState = workingBattle.playerCombatStates[faintedIdx];
               const maxHp = getStats(faintedState, faintedState.stages, faintedState.status).maxHp;
               const v = item.val;
               const healAmt = v === 9999
                 ? maxHp
                 : (typeof v === 'number' && v > 0 && v <= 1)
                   ? Math.floor(maxHp * v)
                   : Math.floor(maxHp * (v || 50) / 100);
               faintedState.currentHp = Math.min(maxHp, healAmt);
               faintedState.status = null;
               faintedState.volatiles = { protected: false, confused: 0, sleepTurns: 0, badlyPoisoned: false };
               logMsg = `使用了 ${item.name}，${party[faintedIdx]?.name || '伙伴'} 恢复了战斗能力！`;
               used = true;
             } else {
               addLog("⚠️ 没有需要复活的伙伴！");
               return;
             }
        }

        if (used) {
            const nextInventory = { ...currentInventory, meds: { ...(currentInventory.meds || {}), [itemKey]: (currentInventory.meds[itemKey] || 0) - 1 } };
            currentInventory = nextInventory;
            inventoryRef.current = nextInventory;
            setInventory(nextInventory);
            grantsIntimacy = true;
        }
    }

    if (category === 'berries') {
        const bItem = BERRIES[itemKey];
        if (!bItem || ((normalizeBerriesInventory(currentInventory.berries)[itemKey] || 0) <= 0)) return;
        const max = getStats(pState, pState.stages, pState.status).maxHp;
        if (bItem.type === 'HP') {
            if (pState.currentHp >= max) { addLog("⚠️ 体力已满！"); return; }
            pState.currentHp = Math.min(max, pState.currentHp + (bItem.val || 30));
            logMsg = `使用了 ${bItem.name}，恢复了体力！`;
            used = true;
        } else if (bItem.type === 'HP_PCT') {
            if (pState.currentHp < max * 0.5) {
                pState.currentHp = Math.min(max, pState.currentHp + Math.floor(max * (bItem.val || 0.25)));
            } else {
                pState.currentHp = Math.min(max, pState.currentHp + 10);
            }
            logMsg = `使用了 ${bItem.name}！`;
            used = true;
        } else if (bItem.type === 'PP') {
            const moves = pState.combatMoves || [];
            const low = moves.filter(m => m.pp < (m.maxPP || 15)).sort((a, b) => a.pp - b.pp)[0];
            if (low) {
                low.pp = Math.min(low.maxPP || 15, low.pp + (bItem.val || 10));
                logMsg = `使用了 ${bItem.name}，${low.name}的PP恢复了！`;
                used = true;
            } else { addLog("⚠️ 技能PP已满！"); return; }
        } else if (bItem.type === 'STATUS') {
            if (bItem.val === 'ALL' || pState.status === bItem.val) {
                pState.status = null;
                if (pState.volatiles) { pState.volatiles.sleepTurns = 0; pState.volatiles.frozenTurns = 0; }
                logMsg = `使用了 ${bItem.name}，异常解除了！`;
                used = true;
            } else { addLog("⚠️ 异常状态不匹配！"); return; }
        } else if (bItem.type === 'STAT_BOOST') {
            if (!pState.stages) pState.stages = { ...DEFAULT_BATTLE_STAGES };
            const k = STAT_BUFF_MAP[bItem.val];
            if (k && pState.currentHp <= max * 0.25) {
                pState.stages[k] = Math.min(6, (pState.stages[k] || 0) + 1);
                logMsg = `使用了 ${bItem.name}，能力上升了！`;
                used = true;
            } else { addLog("⚠️ 树果未触发（需HP低于25%）"); return; }
        } else if (bItem.type === 'CRIT_BOOST' || bItem.type === 'RANDOM_BOOST') {
            if (!pState.stages) pState.stages = { ...DEFAULT_BATTLE_STAGES };
            if (pState.currentHp <= max * 0.25) {
                if (bItem.type === 'CRIT_BOOST') {
                    pState.stages.crit = Math.min(6, (pState.stages.crit || 0) + 2);
                    logMsg = `使用了 ${bItem.name}，容易击中要害！`;
                } else {
                    const opts = ['p_atk', 'p_def', 's_atk', 's_def', 'spd'];
                    const rk = opts[Math.floor(Math.random() * opts.length)];
                    pState.stages[rk] = Math.min(6, (pState.stages[rk] || 0) + 2);
                    logMsg = `使用了 ${bItem.name}，某能力大幅上升！`;
                }
                used = true;
            } else { addLog("⚠️ 树果未触发（需HP低于25%）"); return; }
        } else {
            pState.currentHp = Math.min(max, pState.currentHp + 15);
            logMsg = `使用了 ${bItem.name}！`;
            used = true;
        }
        if (used) {
            const nextInventory = { ...currentInventory, berries: addBerries(currentInventory.berries, itemKey, -1) };
            currentInventory = nextInventory;
            inventoryRef.current = nextInventory;
            setInventory(nextInventory);
            grantsIntimacy = true;
        }
    }

    // 战斗中使用咒具
    if (category === 'cursed') {
      const cItem = CURSED_ITEMS[itemKey];
      if (!cItem || ((currentInventory.cursed || {})[itemKey] || 0) <= 0) return;

      if (cItem.type === 'CE_HEAL') {
        const maxCE = pState.maxCE || 0;
        if (maxCE <= 0) { addLog("⚠️ 该精灵没有咒力！"); return; }
        const currentCE = (workingBattle.sharedPlayerMaxCE || 0) > 0 ? (workingBattle.sharedPlayerCE || 0) : (pState.cursedEnergy || 0);
        const effectiveMaxCE = (workingBattle.sharedPlayerMaxCE || 0) > 0 ? workingBattle.sharedPlayerMaxCE : maxCE;
        if (currentCE >= effectiveMaxCE) { addLog("⚠️ 咒力已满，无需使用！"); return; }
        const heal = Math.floor(maxCE * cItem.val);
        if ((workingBattle.sharedPlayerMaxCE || 0) > 0) {
          workingBattle.sharedPlayerCE = Math.min(workingBattle.sharedPlayerMaxCE, (workingBattle.sharedPlayerCE || 0) + heal);
          (workingBattle.activeIdxs || [workingBattle.activeIdx]).forEach(idx => {
            const ps = workingBattle.playerCombatStates?.[idx];
            if (ps) ps.cursedEnergy = Math.min(ps.maxCE || workingBattle.sharedPlayerMaxCE, workingBattle.sharedPlayerCE);
          });
        } else {
          pState.cursedEnergy = Math.min(maxCE, (pState.cursedEnergy || 0) + heal);
        }
        logMsg = `使用了 ${cItem.name}，恢复了 ${heal} 咒力!`;
        used = true;
      } else if (cItem.type === 'CE_RESTORE') {
        if ((pState.maxCE || 0) <= 0) { addLog("⚠️ 该精灵没有咒力！"); return; }
        const currentCE = (workingBattle.sharedPlayerMaxCE || 0) > 0 ? (workingBattle.sharedPlayerCE || 0) : (pState.cursedEnergy || 0);
        const effectiveMaxCE = (workingBattle.sharedPlayerMaxCE || 0) > 0 ? workingBattle.sharedPlayerMaxCE : pState.maxCE;
        if (currentCE >= effectiveMaxCE) { addLog("⚠️ 咒力已满，无需使用！"); return; }
        if ((workingBattle.sharedPlayerMaxCE || 0) > 0) {
          workingBattle.sharedPlayerCE = Math.min(workingBattle.sharedPlayerMaxCE, (workingBattle.sharedPlayerCE || 0) + cItem.val);
          (workingBattle.activeIdxs || [workingBattle.activeIdx]).forEach(idx => {
            const ps = workingBattle.playerCombatStates?.[idx];
            if (ps) ps.cursedEnergy = Math.min(ps.maxCE || workingBattle.sharedPlayerMaxCE, workingBattle.sharedPlayerCE);
          });
        } else {
          pState.cursedEnergy = Math.min(pState.maxCE, (pState.cursedEnergy || 0) + cItem.val);
        }
        logMsg = `使用了 ${cItem.name}，恢复了 ${cItem.val} 咒力!`;
        used = true;
      } else if (cItem.type === 'CE_BOOST') {
        pState.cursedBoost = (pState.cursedBoost || 0) + cItem.val;
        logMsg = `使用了 ${cItem.name}，术式威力提升 ${cItem.val * 100}%!`;
        used = true;
      } else if (cItem.type === 'ANTI_DOMAIN') {
        if (workingBattle.activeDomain && workingBattle.activeDomain.ownerSide === 'enemy') {
          workingBattle.activeDomain = null;
          logMsg = `使用了 ${cItem.name}，破除了敌方领域!`;
          used = true;
        } else { addLog("⚠️ 当前没有敌方领域！"); return; }
      } else if (cItem.type === 'SEAL') {
        const enemy = workingBattle.enemyParty?.[itemTargetEnemyIdx];
        if (enemy && !workingBattle.isBoss) {
          if (Math.random() < cItem.val) {
            const enemyMaxHp = getStats(enemy, enemy.stages, enemy.status).maxHp || enemy.currentHp || 1;
            const sealDamage = Math.max(1, Math.floor(enemyMaxHp * 0.35));
            const sealedEnemy = {
              ...enemy,
              currentHp: Math.max(1, (enemy.currentHp || 1) - sealDamage),
              stages: {
                ...(enemy.stages || DEFAULT_BATTLE_STAGES),
                p_atk: Math.max(-6, (enemy.stages?.p_atk || 0) - 2),
                s_atk: Math.max(-6, (enemy.stages?.s_atk || 0) - 2),
                spd: Math.max(-6, (enemy.stages?.spd || 0) - 1),
              },
              volatiles: {
                ...(enemy.volatiles || {}),
                flinched: true,
              },
            };
            workingBattle.enemyParty[itemTargetEnemyIdx] = sealedEnemy;
            logMsg = `使用了 ${cItem.name}，封印了 ${enemy.name}！造成${sealDamage}伤害并削弱攻势`;
            used = true;
          } else {
            logMsg = `使用了 ${cItem.name}，但封印失败了...`;
            used = true;
          }
        } else { addLog(workingBattle.isBoss ? "⚠️ 对首领无效！" : "⚠️ 无效目标！"); return; }
      }

      if (used) {
        const nextInventory = { ...currentInventory, cursed: { ...(currentInventory.cursed || {}), [itemKey]: (currentInventory.cursed[itemKey] || 0) - 1 } };
        currentInventory = nextInventory;
        inventoryRef.current = nextInventory;
        setInventory(nextInventory);
        }
    }

    if (used) {
        if (grantsIntimacy) {
          const currentParty = partyRef.current || [];
          if (currentParty[targetIdx]) {
            const nextParty = [...currentParty];
            nextParty[targetIdx] = { ...nextParty[targetIdx], intimacy: Math.min(255, (nextParty[targetIdx].intimacy || 0) + 1) };
            partyRef.current = nextParty;
            setParty(nextParty);
          }
        }
        setShowBallMenu(false); 
        addLog(logMsg);
        setBattle(prev => prev ? ({
          ...prev,
          playerCombatStates: workingBattle.playerCombatStates.map(p => ({ ...p })),
          enemyParty: workingBattle.enemyParty.map(e => ({ ...e })),
          activeDomain: workingBattle.activeDomain ? { ...workingBattle.activeDomain } : null,
          sharedPlayerCE: workingBattle.sharedPlayerCE ?? prev.sharedPlayerCE,
          sharedPlayerChakra: workingBattle.sharedPlayerChakra ?? prev.sharedPlayerChakra,
          phase: 'busy',
        }) : prev);
        setAnimEffect({ type: 'HEAL', target: 'player' });
        await wait(800);
        setAnimEffect(null);
        const sealedEnemy = workingBattle.enemyParty?.[itemTargetEnemyIdx];
        if (sealedEnemy && sealedEnemy.currentHp <= 0) {
          const { newParty, logMsg: winLog } = processDefeatedEnemy(sealedEnemy, party, workingBattle);
          setParty(newParty);
          addLog(winLog);
          const nextEnemyIdx = workingBattle.enemyParty.findIndex((p) => p.currentHp > 0);
          if (nextEnemyIdx !== -1) {
            setBattle(prev => prev ? ({
              ...prev,
              playerCombatStates: workingBattle.playerCombatStates.map(p => ({ ...p })),
              enemyParty: workingBattle.enemyParty.map(e => ({ ...e })),
              enemyActiveIdx: nextEnemyIdx,
              phase: 'input',
              logs: [`对手派出了 ${workingBattle.enemyParty[nextEnemyIdx].name}!`, ...prev.logs],
            }) : null);
          } else {
            pendingJutsuWinForBountyRef.current = false;
            handleWin(newParty, workingBattle);
          }
        } else {
          if (workingBattle.isDouble) {
            const skipActions = (workingBattle.activeIdxs || []).map(idx => ({ moveIdx: -1, activeIdx: idx }));
            await executeDoubleRound(skipActions, workingBattle);
          } else {
            await enemyTurn(workingBattle);
          }
        }
    }
    } catch (e) { console.error('useBattleItem error:', e); setBattle(prev => prev ? ({ ...prev, phase: 'input' }) : prev); }
    finally { battleSpecialActionLockRef.current = false; }
  };


    // ==========================================
  // [修正] 初始精灵确认 (初始化新版背包结构)
  // ==========================================
  const confirmStarter = (preGeneratedPet) => {
    const registeredName = tempName.trim();
    if (!registeredName || !preGeneratedPet || partyRef.current.length > 0) return;
    setTrainerName(registeredName);
    // 🔥 关键修改：不再调用 createPet，而是直接使用传进来的对象
    // 只需要更新一下 uid 确保唯一性即可
    const newPet = { ...preGeneratedPet, uid: Date.now() };
    partyRef.current = [newPet];
    // 2. 初始化玩家状态
    setParty([newPet]);
    setCaughtDex([newPet.id]);
    setGold(2000);
    
    // ▼▼▼▼▼▼▼▼▼▼ 核心修复点 ▼▼▼▼▼▼▼▼▼▼
    setInventory({ 
        balls: { poke: 15, great: 2, ultra: 0, master: 0, net:0, dusk:0, quick:0, timer:0, heal:0 }, 
        meds: { potion: 10, super_potion: 2 },
        stones: {},
        tms: {},  
        misc: {},
        cursed: {},
        eggs: [],
        berries: { oran: 8 },
        exp_candy: 0,
        max_candy: 0,
    });
    // ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲
    
    // 3. 初始化剧情
    setStoryProgress(0);
    setStoryStep(0);
    setViewedIntros([]);

    // 4. 进入第一张地图 (触发剧情对话)
    enterMap(1);
    
    // 5. 成就：选择初始精灵
    updateAchStat({ starterChosen: true, totalCaught: 1 });
    
    showMapToast('🎉', '冒险开始', `恭喜！你获得了 ${newPet.name}！冒险开始了！`, 3000);
    setTimeout(() => showMapToast('💡', '新手提示', '找到地图上的 ❗ 剧情点开始主线任务！草丛中可能遭遇野生精灵', 4000), 3500);
    setTimeout(() => showMapToast('📱', '操作指南', '方向键/WASD移动 · 空格与NPC互动 · 底部菜单进入各系统', 4000), 7500);
  };

    // ==========================================

  const checkEvoCondition = (pet, evoDex, options = {}) => {
    // 统一走纯函数判定，避免升级、糖果、树果和进化石各自使用不同规则。
    const srcDex = POKEDEX.find(entry => entry.id === pet.id);
    const condition = srcDex?.evoCondition || evoDex?.evoCondition;
    return evolutionConditionMatches(condition, pet, { timePhase, weather, ...options });
  };

  const applySingleBattleDot = (battleState, addLogFn = addLog) => {
    if (!battleState || battleState.isDouble) return { playerFainted: false, enemyFainted: false };
    const pairs = [
      { unit: battleState.playerCombatStates?.[battleState.activeIdx], side: 'player' },
      { unit: battleState.enemyParty?.[battleState.enemyActiveIdx], side: 'enemy' },
    ];
    let playerFainted = false;
    let enemyFainted = false;
    pairs.forEach(({ unit, side }) => {
      if (!unit || unit.currentHp <= 0 || unit.trait === 'magic_guard') return;
      if (unit.status !== 'BRN' && unit.status !== 'PSN') return;
      const eFx = getEquipEffects(unit);
      const immune = eFx.some(fx => fx.id === 'status_immune' && (fx.val === 'ALL' || fx.val === unit.status));
      if (immune) {
        unit.status = null;
        addLogFn(`🌸 ${unit.name} 的饰品净化了异常状态！`);
        return;
      }
      const badlyPoisoned = unit.status === 'PSN' && unit.volatiles?.badlyPoisoned;
      const badlyPoisonedTurns = unit.volatiles?.badlyPoisonedTurns || 1;
      let dot = calcResidualStatusDamage(getStats(unit).maxHp, unit.status, { badlyPoisoned, badlyPoisonedTurns });
      if (badlyPoisoned) unit.volatiles.badlyPoisonedTurns = badlyPoisonedTurns + 1;
      // 门派8五毒心法：中毒DOT+20%（对敌方中毒精灵）
      if (unit.status === 'PSN' && side === 'enemy') {
        const ps = battleState?._playerSectState;
        if (ps?.playerSect === 8 && getXinfaTier(ps.sectXinfaLevels, 8) >= 3) dot = Math.floor(dot * 1.2);
      }
      unit.currentHp = Math.max(0, unit.currentHp - dot);
      if (side === 'player' && battleState) markPlayerTookDamage(battleState);
      addLogFn(`${unit.name} 受到 ${unit.status === 'BRN' ? '灼伤' : unit.volatiles?.badlyPoisoned ? '剧毒' : '毒'} 伤害 ${dot}!`);
      if (unit.currentHp <= 0) {
        if (side === 'player') playerFainted = true;
        else enemyFainted = true;
      }
    });
    return { playerFainted, enemyFainted };
  };

  const getInitialResource = (maxValue, config = {}) => {
    const configuredPct = Number.isFinite(config.initialPercent) ? config.initialPercent : 0.25;
    const pct = configuredPct;
    return Math.max(0, Math.min(maxValue || 0, Math.floor((maxValue || 0) * pct)));
  };

  const getBattleResourceValue = (battleState, unit, source, kind) => {
    const isPlayerSide = source === 'player';
    const reserved = isPlayerSide ? getQueuedDoubleMoveResourceCost(battleState, kind) : 0;
    if (kind === 'ce') {
      const sharedMax = isPlayerSide ? battleState?.sharedPlayerMaxCE : battleState?.sharedEnemyMaxCE;
      const current = (sharedMax || 0) > 0
        ? (isPlayerSide ? (battleState?.sharedPlayerCE || 0) : (battleState?.sharedEnemyCE || 0))
        : (unit?.cursedEnergy || 0);
      return Math.max(0, current - reserved);
    }
    const sharedMax = isPlayerSide ? battleState?.sharedPlayerMaxChakra : battleState?.sharedEnemyMaxChakra;
    const current = (sharedMax || 0) > 0
      ? (isPlayerSide ? (battleState?.sharedPlayerChakra || 0) : (battleState?.sharedEnemyChakra || 0))
      : (unit?.chakra || 0);
    return Math.max(0, current - reserved);
  };

  const canUseCombatMove = (battleState, unit, move, source = 'player') => {
    if (!move) return false;
    if (move.isBattleCommand) return canUseCrossoverCommand(battleState, unit, move, source, getBattleResourceValue(battleState, unit, source, 'ce'));
    if (move.isUltraFinisher) return !!unit?.ultraTransformed && unit.ultraTurnsLeft > 0 && move.pp > 0;
    if (move.isCursed) {
      return getBattleResourceValue(battleState, unit, source, 'ce') >= (move.ceCost || 0)
        && (move.pp === undefined || move.pp > 0)
        && !((unit?.cursedCooldowns?.[move.id || move.name] || 0) > 0);
    }
    if (move.isJutsu) {
      const effects = source === 'player' ? (battleState?._resonanceFx || {}) : {};
      return getBattleResourceValue(battleState, unit, source, 'chakra') >= getEffectiveChakraCost(move, effects)
        && (move.pp === undefined || move.pp > 0)
        && !((unit?.jutsuCooldowns?.[move.jutsuId || move.name] || 0) > 0);
    }
    if (move.isMartialArt) {
      const hasPP = (move.pp === undefined || move.pp > 0);
      const hasMomentum = !(move.momentumCost > 0 && (battleState?._sectMomentum || 0) < move.momentumCost);
      return hasPP && hasMomentum;
    }
    return move.pp === undefined || move.pp > 0;
  };

  const getUnitTypeList = (unit) => [...new Set([unit?.type, unit?.secondaryType, unit?.type2].filter(Boolean))];

  const getUnitOffensiveTypeList = (unit) => {
    const moveTypes = (unit?.combatMoves || unit?.moves || [])
      .filter(move => move?.t && (move.p || 0) > 0)
      .map(move => move.t);
    return [...new Set([...moveTypes, ...getUnitTypeList(unit)])];
  };

  const getMoveTypeMultiplier = (move, target, battleState) => {
    if (!move?.t || !target) return 1;
    return getUnitTypeList(target).reduce((mult, type) => mult * getTypeMod(move.t, type, battleState), 1);
  };

  const isStatusImmuneToMove = (move, target) => {
    const status = move?.effect?.status;
    if (!status || !target) return false;
    const targetTypes = getUnitTypeList(target);
    return (status === 'BRN' && targetTypes.includes('FIRE'))
      || (status === 'FRZ' && targetTypes.includes('ICE'))
      || (status === 'PSN' && (targetTypes.includes('POISON') || targetTypes.includes('STEEL')))
      || (status === 'PAR' && targetTypes.includes('ELECTRIC'));
  };

  const getEnemyAiStyle = (battleState, enemyUnit, opts = {}) => {
    const tacticId = opts.aiTactic || battleState?.trainerTactic?.id || 'balanced';
    const pressureLevel = Math.max(0, Math.min(2, battleState?.trainerPressure?.level || 0));
    const enemyParty = battleState?.enemyParty || [];
    const enemyIdx = enemyParty.findIndex(p => p === enemyUnit || (p?.uid && enemyUnit?.uid && p.uid === enemyUnit.uid));
    const isAce = enemyIdx >= 0 && enemyIdx === enemyParty.length - 1;
    const baseTopChance = opts.isHardBattle ? 0.78 : 0.55;
    const topChanceBonus = tacticId === 'aggressive' ? 0.06
      : tacticId === 'ace_focus' ? (isAce ? 0.10 : 0.04)
      : tacticId === 'deep_roster' ? 0.04
      : tacticId === 'sturdy' ? 0.03
      : 0;
    const scoreNoise = tacticId === 'ace_focus' && isAce ? 5
      : tacticId === 'aggressive' ? 7
      : opts.isHardBattle ? 8
      : 24;
    return {
      tacticId,
      isAce,
      topMoveChance: Math.min(0.9, baseTopChance + topChanceBonus + pressureLevel * 0.03),
      scoreNoise: Math.max(4, scoreNoise - pressureLevel * 2),
    };
  };

  const scoreCombatMoveForTarget = (battleState, attacker, target, move, source = 'enemy', opts = {}) => {
    if (!attacker || !target || !move || !canUseCombatMove(battleState, attacker, move, source)) return -Infinity;
    const isHardBattle = !!opts.isHardBattle;
    const aiStyle = opts.aiStyle || getEnemyAiStyle(battleState, attacker, opts);
    const aiTactic = aiStyle.tacticId;
    const attackerStats = getStats(attacker, attacker.stages, attacker.status);
    const targetStats = getStats(target, target.stages, target.status);
    const hpRatio = attacker.currentHp / Math.max(1, attackerStats.maxHp || 1);
    const targetHpRatio = target.currentHp / Math.max(1, targetStats.maxHp || 1);
    const effect = move.effect || {};
    let score = 0;

    if ((move.p || 0) > 0) {
      const typeMod = getMoveTypeMultiplier(move, target, battleState);
      if (typeMod <= 0) return -Infinity;
      const atkStat = (move.cat === 'special' ? attackerStats.s_atk : attackerStats.p_atk) || 1;
      const defStat = Math.max(1, (move.cat === 'special' ? targetStats.s_def : targetStats.p_def) || 1);
      const stab = move.t && getUnitTypeList(attacker).includes(move.t) ? 1.35 : 1;
      const acc = move.alwaysHit || move.acc === 0 ? 1 : Math.max(0.5, Math.min(1, (Number(move.acc) || 100) / 100));
      score = (move.p || 40) * typeMod * stab * Math.pow(atkStat / defStat, 0.35) * acc;
      if (targetHpRatio < 0.35) score += 24;
      if (targetHpRatio < 0.18) score += 34;
      if (effect.drain || effect.hpDrain) score += hpRatio < 0.65 ? 18 : 6;
      if (effect.flinch) score += 6;
      if (effect.defDown || effect.sDefDown || effect.spdDown || effect.atkDown || effect.accDown) score += 8;
      if (move.isCursed || move.isJutsu || move.isFruitMove || move.isExtra) score += isHardBattle ? 12 : 5;
      if (aiTactic === 'aggressive') {
        score += 10 + (typeMod > 1 ? 10 : 0);
      }
      if (aiTactic === 'ace_focus' && aiStyle.isAce) {
        score += 8 + (targetHpRatio < 0.45 ? 12 : 0);
      }
      if (aiTactic === 'sturdy' && (effect.drain || effect.hpDrain) && hpRatio < 0.7) {
        score += 12;
      }
    } else if (effect.type === 'HEAL' || move.t === 'HEAL' || (move.val && move.val > 0)) {
      if (hpRatio > 0.7) return -Infinity;
      score = hpRatio < 0.3 ? 86 : hpRatio < 0.5 ? 58 : 24;
      if (aiTactic === 'sturdy') score += hpRatio < 0.55 ? 18 : 6;
      if (aiTactic === 'ace_focus' && aiStyle.isAce && hpRatio < 0.45) score += 10;
    } else if (effect.type === 'BUFF') {
      const statKeys = [effect.stat, effect.stat2, effect.stat3].filter(Boolean);
      if (statKeys.length && statKeys.every(k => (attacker.stages?.[k] || 0) >= 6)) return -Infinity;
      if (hpRatio < 0.35) return -Infinity;
      score = 34 + Math.max(0, 3 - (battleState?.turnCount || 0)) * 7;
      if (aiTactic === 'ace_focus' && aiStyle.isAce) score += 10;
      if (aiTactic === 'aggressive' && (battleState?.turnCount || 0) <= 2) score += 6;
    } else if (effect.type === 'DEBUFF') {
      const statKeys = [effect.stat, effect.stat2, effect.stat3].filter(Boolean);
      if (statKeys.length && statKeys.every(k => (target.stages?.[k] || 0) <= -6)) return -Infinity;
      score = 36 + (targetHpRatio > 0.45 ? 10 : 0);
      if (aiTactic === 'deep_roster') score += 12;
    } else if (effect.type === 'STATUS') {
      if (effect.status !== 'CON' && (target.status || isStatusImmuneToMove(move, target))) return -Infinity;
      if (effect.status === 'CON' && target.volatiles?.confused) return -Infinity;
      score = 40 + (targetHpRatio > 0.4 ? 8 : 0);
      if (aiTactic === 'deep_roster') score += 12;
    } else if (effect.type === 'PROTECT') {
      const streak = attacker.volatiles?.protectStreak || 0;
      score = hpRatio < 0.35 ? 30 : 12;
      score -= streak * 18;
      if (aiTactic === 'sturdy' && hpRatio < 0.55) score += 12;
    } else {
      score = 8;
    }

    if (attacker.activeVow?.reward?.atkMult > 1 || attacker.activeVow?.reward?.nextMovePower > 1) {
      score += (move.p || 0) > 0 ? 35 : -20;
    }
    if (move.priority) score += move.priority * 10;
    return score + Math.random() * aiStyle.scoreNoise;
  };

  const chooseEnemyCombatAction = (battleState, enemyUnit, targets, opts = {}) => {
    const aiStyle = getEnemyAiStyle(battleState, enemyUnit, opts);
    const scoringOpts = { ...opts, aiStyle };
    const targetList = normalizeCombatTargets(targets, battleState?.activeIdx);
    const moves = (enemyUnit?.combatMoves || enemyUnit?.moves || []).filter(m => canUseCombatMove(battleState, enemyUnit, m, 'enemy'));
    if (!enemyUnit || targetList.length === 0 || moves.length === 0) {
      return { move: { name: '挣扎', p: 20, t: 'NORMAL', cat: 'physical', acc: 100, pp: 99, maxPP: 99, effect: { recoil: 0.25 } }, targetIdx: targetList[0]?.idx };
    }
    const scored = [];
    for (const move of moves) {
      for (const target of targetList) {
        const score = scoreCombatMoveForTarget(battleState, enemyUnit, target.unit, move, 'enemy', scoringOpts);
        if (Number.isFinite(score)) scored.push({ move, targetIdx: target.idx, score });
      }
    }
    if (scored.length === 0) {
      return { move: { name: '挣扎', p: 20, t: 'NORMAL', cat: 'physical', acc: 100, pp: 99, maxPP: 99, effect: { recoil: 0.25 } }, targetIdx: targetList[0]?.idx };
    }
    scored.sort((a, b) => b.score - a.score);
    if (opts.isHardBattle) {
      return Math.random() < aiStyle.topMoveChance ? scored[0] : scored[Math.floor(Math.random() * Math.min(3, scored.length))];
    }
    return Math.random() < aiStyle.topMoveChance ? scored[0] : scored[Math.floor(Math.random() * Math.min(4, scored.length))];
  };

  // [核心] 属性计算函数 - 委托给 utils/statsCalculator.js
  // ==========================================
  function getStats(pet, stages = null, status = null, gangBonusOverride = undefined) {
    const relicFx = getEquippedRelicEffects(relics);
    const resonanceFx = pet ? calcResonanceBonuses(pet, getResonanceContext()) : {};
    const merged = mergeStatEffectMults(relicFx, resonanceFx);
    const resolvedGangBonus = gangBonusOverride !== undefined
      ? gangBonusOverride
      : (pet?.isEnemy ? (pet._gangBonus || {}) : undefined);
    return getStatsRaw(pet, stages, status, {
      currentTitle, gang, housing,
      homeScoreBonus: getSpouseBonusesForState(marriageRef.current).homeScore || 0,
      relicEffects: relicFx,
      gangSkillCapBonus: getGangSkillCapBonus(kingdomWar),
      sectEffectMult: merged.sectEffectMult,
      gangSkillMult: relicFx.gangSkillMult || 1,
      playerSect: sectPlayer?.playerSect,
      playerSubSect: sectPlayer?.playerSubSect,
    }, resolvedGangBonus);
  }

  const getAllOwnedPets = () => [...(party || []), ...(box || [])];

  const getFruitMinTurn = () => getFruitTransformMinTurn(getEquippedRelicEffects(relics));

  const assignDevilFruitToPartyPet = (petIndex, fruitId) => {
    const lockKey = `party:${petIndex}`;
    if (fruitAssignmentLocksRef.current.has(lockKey)) return false;
    fruitAssignmentLocksRef.current.add(lockKey);
    try {
      const currentParty = partyRef.current || [];
      const pet = currentParty[petIndex];
      if (!pet || !getFruitById(fruitId)) return false;
      const currentInventory = fruitInventoryRef.current || [];
      let nextInventory = [...currentInventory];
      let nextFruit = fruitId;
      if (pet.devilFruit === fruitId) {
        nextInventory.push(fruitId);
        nextFruit = null;
      } else {
        const selectedIndex = nextInventory.indexOf(fruitId);
        if (selectedIndex < 0) {
          showMapToast('❌', '果实不足', '背包中已没有这颗果实', 1500);
          return false;
        }
        nextInventory.splice(selectedIndex, 1);
        if (pet.devilFruit) nextInventory.push(pet.devilFruit);
      }
      const nextParty = currentParty.map((entry, index) => index === petIndex ? { ...entry, devilFruit: nextFruit } : entry);
      fruitInventoryRef.current = nextInventory;
      partyRef.current = nextParty;
      flushSync(() => {
        setFruitInventory(nextInventory);
        setParty(nextParty);
      });
      if (viewStatPet?.uid === pet.uid) setViewStatPet(nextParty[petIndex]);
      const fruit = getFruitById(fruitId);
      showMapToast('🍎', nextFruit ? '装备果实' : '卸下果实', nextFruit ? `${fruit.name} → ${pet.name}` : `${pet.name} · ${fruit.name}`, 2000);
      return true;
    } finally {
      window.setTimeout(() => fruitAssignmentLocksRef.current.delete(lockKey), 0);
    }
  };

  const awakenPet = (petUid) => {
    const pet = party.find(p => p.uid === petUid) || box.find(p => p.uid === petUid);
    if (!pet) return;
    const check = canAwakenPet(pet, getAllOwnedPets());
    if (!check.ok) { showMapToast('🔒', '无法觉醒', check.reason, 2500); return; }
    const moveTemplate = getAwakeningMove(pet.type || 'NORMAL');
    const awakenMove = { ...moveTemplate, maxPP: moveTemplate.maxPP || moveTemplate.pp, isAwakenMove: true };
    const applyAwaken = (p) => {
      if (p.uid !== petUid) return p;
      const moves = [...(p.moves || [])];
      const emptyIdx = moves.findIndex(m => !m);
      if (emptyIdx >= 0) moves[emptyIdx] = awakenMove;
      else if (moves.length < 4) moves.push(awakenMove);
      else {
        const replaceIdx = moves.findIndex(m => !m?.isAwakenMove && (m?.p || 0) <= 80);
        moves[replaceIdx >= 0 ? replaceIdx : 3] = awakenMove;
      }
      const baseName = (p.name || '').replace(/^[🌟✨]+/, '');
      return { ...p, awakened: true, moves, name: `🌟${baseName}` };
    };
    setParty(prev => prev.map(applyAwaken));
    setBox(prev => prev.map(applyAwaken));
    updateAchStat({ petsAwakened: 1 });
    showMapToast('✨', '精灵觉醒！', `${pet.name} 觉醒成功，获得觉醒技「${awakenMove.name}」`, 3500);
    setFusionState(prev => ({ ...prev, awakeningTiers: { ...(prev.awakeningTiers || {}), [petUid]: prev.awakeningTiers?.[petUid] || 'normal' } }));
  };

  const upgradeAwakeningTier = (petUid, tierId) => {
    const lockKey = `${petUid}:${tierId}`;
    if (awakeningActionLocksRef.current.has(lockKey)) return false;
    awakeningActionLocksRef.current.add(lockKey);
    try {
      const currentParty = partyRef.current || [];
      const currentBox = boxRef.current || [];
      const pet = currentParty.find(p => p.uid === petUid) || currentBox.find(p => p.uid === petUid);
      if (!pet) return false;
      const currentFusion = fusionStateRef.current || fusionState;
      const check = checkAwakeningTier(pet, tierId, { fusionState: currentFusion, kingdomWar: kingdomWarRef.current });
      if (!check.ok) { showMapToast('🔒', '条件不足', check.reason, 2500); return false; }
      const tier = AWAKENING_TIERS[tierId];
      const applyTier = entry => entry.uid === petUid ? applyAwakeningTierToPet(entry, tierId) : entry;
      const nextParty = currentParty.map(applyTier);
      const nextBox = currentBox.map(applyTier);
      partyRef.current = nextParty;
      boxRef.current = nextBox;
      flushSync(() => {
        setParty(nextParty);
        setBox(nextBox);
      });
      if (viewStatPet?.uid === petUid) setViewStatPet(prev => applyTier(prev));
      commitFusionState(prev => ({ ...prev, awakeningTiers: { ...(prev.awakeningTiers || {}), [petUid]: tierId } }));
      if (tier.rewards?.title) unlockTitle(tier.rewards.title);
      updateAchStat({ fusionAwakeningTiers: 1 });
      if (tierId === 'strategic') updateAchStat({ strategicAwakeningCount: 1 });
      showMapToast(tier.icon, tier.name, `${pet.name} 完成${tier.name}！`, 3500);
      return true;
    } finally {
      window.setTimeout(() => awakeningActionLocksRef.current.delete(lockKey), 0);
    }
  };

  const equipRelic = (relicId) => {
    if (relicActionLockRef.current) return;
    relicActionLockRef.current = true;
    try {
      const current = relicsRef.current || { equipped: [], owned: [] };
      if (!current.owned?.includes(relicId)) return;
      const equipped = [...(current.equipped || [])];
      let nextEquipped;
      if (equipped.includes(relicId)) {
        nextEquipped = equipped.filter(id => id !== relicId);
      } else {
        if (equipped.length >= MAX_EQUIPPED_RELICS) {
          showMapToast('⚠️', '遗物槽已满', `最多装备 ${MAX_EQUIPPED_RELICS} 个遗物`, 2000);
          return;
        }
        nextEquipped = [...equipped, relicId];
      }
      const next = { ...current, equipped: nextEquipped };
      relicsRef.current = next;
      setRelics(next);
    } finally {
      window.setTimeout(() => { relicActionLockRef.current = false; }, 0);
    }
  };

  const grantRelicDrop = (relic) => {
    if (!relic) return;
    const current = relicsRef.current || { equipped: [], owned: [] };
    const alreadyOwned = (current.owned || []).includes(relic.id);
    if (alreadyOwned) {
      const goldComp = getDuplicateRelicGold(relic);
      goldRef.current += goldComp;
      setGold(goldRef.current);
      updateAchStat({ totalGoldEarned: goldComp });
      showMapToast('♻️', '重复遗物', `${relic.name} 已拥有，转化为 ${goldComp.toLocaleString()} 金币`, 2500);
      return;
    }
    const next = { ...current, owned: [...new Set([...(current.owned || []), relic.id])] };
    relicsRef.current = next;
    setRelics(next);
    updateAchStat({ relicsCollected: 1 });
    setRelicDropModal(relic);
  };

  const addGuardianScore = (pts) => {
    if (!pts) return;
    const relicMult = getEquippedRelicEffects(relics).guardianScoreMult || 1;
    const gain = Math.max(1, Math.floor(pts * relicMult));
    setGuardianScore(prev => prev + gain);
    updateAchStat({ guardianScoreTotal: gain });
  };

  useEffect(() => {
    const unclaimed = getUnclaimedGuardianMilestones(guardianScore, guardianMilestonesClaimedRef.current);
    if (!unclaimed.length) return;
    guardianMilestonesClaimedRef.current = [...new Set([
      ...guardianMilestonesClaimedRef.current,
      ...unclaimed.map(m => m.score),
    ])];
    setGuardianMilestonesClaimed(guardianMilestonesClaimedRef.current);
    unclaimed.forEach(m => {
      if (m.reward?.title) unlockTitle(m.reward.title);
      if (m.reward?.gold) { goldRef.current += m.reward.gold; setGold(goldRef.current); updateAchStat({ totalGoldEarned: m.reward.gold }); }
      if (m.reward?.item) {
        const isBall = !!BALLS[m.reward.item] || m.reward.item.includes('ball');
        const cat = isBall ? 'balls' : 'meds';
        setInventory(p => ({ ...p, [cat]: { ...p[cat], [m.reward.item]: (p[cat]?.[m.reward.item] || 0) + (m.reward.itemCount || 1) } }));
      }
      if (m.reward?.petId) {
        const gp = createPet(m.reward.petId, m.reward.petLevel || 70, true, !!m.reward.shiny);
        gp.name = `🌿${gp.name}`;
        const currentGuardianParty = partyRef.current || [];
        if (currentGuardianParty.length < 6) {
          const nextGuardianParty = [...currentGuardianParty, gp];
          partyRef.current = nextGuardianParty;
          setParty(nextGuardianParty);
        } else {
          boxRef.current = [...(boxRef.current || []), gp];
          setBox(boxRef.current);
        }
        if (!caughtDexRef.current.includes(m.reward.petId)) {
          caughtDexRef.current = [...caughtDexRef.current, m.reward.petId];
          setCaughtDex(caughtDexRef.current);
        }
      }
    });
  }, [guardianScore, guardianMilestonesClaimed.length]); // eslint-disable-line

  const getResonanceContext = () => ({ narutoState, kingdomWar, gang, allPets: getAllOwnedPets(), fusionState, sanctuaryState, regionEcology, currentMapId });
  const getActiveResonanceForPet = (pet) => calcResonanceBonuses(pet, getResonanceContext());

  // ==========================================
  // [新增] 启动门派首席挑战
  // ==========================================
  const startSectChallenge = (sectId) => {
      const config = SECT_CHIEFS_CONFIG[sectId];
      const sectInfo = SECT_DB[sectId];
      if (!config || !sectInfo) { showMapToast('❌', '提示', '⛔ 门派信息不存在！', 1500); return; }

      if ((partyRef.current || party).length < 3) {
          showMapToast('⚠️', '提示', '门派试炼非常危险，请至少携带 3 只精灵！', 1500);
          return;
      }

      setConfirmModal({ title:'⚔️ 挑战确认', msg:`挑战【${sectInfo.name}】首席？`, onOk: () => {
        const lockKey = `challenge:${sectId}`;
        if (sectActionLocksRef.current.has(lockKey) || battle) return;
        const currentParty = partyRef.current || party;
        if (currentParty.length < 3) {
          showMapToast('⚠️', '队伍不足', '门派试炼需要至少3只精灵', 1800);
          return;
        }
        sectActionLocksRef.current.add(lockKey);
        const enemyParty = [];
        const teamIds = SECT_TEAMS[sectId] || [];
        const playerMaxLv = Math.max(...currentParty.map(p => p.level || 1));
        const baseLv = Math.max(60, Math.min(95, playerMaxLv + 5));
        teamIds.forEach((petId, idx) => {
          const isAce = idx === 0;
          const level = isAce ? Math.min(100, baseLv + 5) : baseLv;
          const pet = createPet(petId, level, true, isAce);
          pet.sectId = parseInt(sectId, 10);
          pet.sectLevel = isAce ? 10 : 8;
          if (isAce) pet.name = `[首席] ${pet.name}`;
          enemyParty.push(pet);
        });
        const started = attemptBattleStart('门派首席挑战', () => startBattle({
          id: 8000 + sectId,
          name: `${config.title} ${config.name}`,
          customParty: enemyParty,
          drop: 10000,
        }, 'sect_challenge'), () => sectActionLocksRef.current.delete(lockKey));
        if (started) window.setTimeout(() => sectActionLocksRef.current.delete(lockKey), 0);
      }});
  };
    // ==========================================
  // [新增] 打开门派阵容详情
  // ==========================================
  const openSectTeamDetail = (sectId) => {
      const teamIds = SECT_TEAMS[sectId] || [];
      const sectInfo = SECT_DB[sectId];
      if (!sectInfo) { showMapToast('❌', '错误', '门派信息不存在', 1500); return; }
      
      const playerMaxLv = Math.max(...party.map(p => p.level || 1), 5);
      const baseLv = Math.max(60, Math.min(95, playerMaxLv + 5));
      const previewTeam = teamIds.map((id, idx) => {
          const isAce = idx === 0;
          const level = isAce ? Math.min(100, baseLv + 5) : baseLv;
          
          // 创建临时对象用于展示
          const pet = createPet(id, level, true, isAce); 
          pet.sectId = sectId;
          pet.sectLevel = isAce ? 10 : 8; // 模拟高层心法
          if (isAce) pet.name = `[首席] ${pet.name}`;
          
          return pet;
      });

      setViewSectTeam({
          name: sectInfo.name,
          color: sectInfo.color,
          team: previewTeam
      });
  };

  const ensureSectDailyTasks = () => {
    setSectPlayer(prev => {
      const today = getLocalDateStr();
      const sameDay = prev.sectDailyDate === today;
      const currentTasks = prev.sectDailyTasks || [];
      const tasks = sameDay ? repairSectDailyTasks(currentTasks, today, prev.playerSect) : generateSectDailyTasks(today, prev.playerSect);
      if (tasks === currentTasks) return prev;
      return {
        ...prev,
        sectDailyDate: today,
        sectDailyTasks: tasks,
      };
    });
  };

  useEffect(() => { if (sectPlayer?.playerSect) ensureSectDailyTasks(); }, []); // eslint-disable-line
  useEffect(() => {
    const timer = setInterval(() => { if (sectPlayer?.playerSect) ensureSectDailyTasks(); }, 60000);
    return () => clearInterval(timer);
  }, [sectPlayer?.playerSect]); // eslint-disable-line

  const addSectResources = (delta) => {
    setSectPlayer(prev => {
      const sectResources = { ...prev.sectResources };
      Object.entries(delta || {}).forEach(([k, v]) => { sectResources[k] = (sectResources[k] || 0) + v; });
      const reputation = sectResources.reputation || 0;
      const sectRank = getSectRankByRep(reputation);
      return { ...prev, sectResources, sectRank };
    });
  };

  const joinPlayerSect = (sectId) => {
    if (badges.length < SECT_JOIN_REQ_BADGES) {
      showMapToast('🔒', '未解锁', `需要至少 ${SECT_JOIN_REQ_BADGES} 枚徽章才能拜入门派`, 2500); return;
    }
    if (sectPlayer.playerSect) {
      showMapToast('⚠️', '已入门派', '更换门派需消耗1500声望', 2000); return;
    }
    const sect = SECT_DB[sectId];
    setSectPlayer(prev => {
      const newRep = (prev.sectResources?.reputation || 0) + 50;
      return {
        ...prev,
        playerSect: sectId,
        sectRank: getSectRankByRep(newRep),
        sectResources: { ...prev.sectResources, reputation: newRep },
        sectXinfaLevels: { ...prev.sectXinfaLevels, [sectId]: 1 },
        sectMartialArts: prev.sectMartialArts?.includes(`s${sectId}_basic`) ? prev.sectMartialArts : [...(prev.sectMartialArts || []), `s${sectId}_basic`],
      };
    });
    ensureSectDailyTasks();
    showMapToast(sect?.emoji || '🏔️', '拜入成功', `你已拜入【${sect?.name}】，成为记名弟子！`, 3500);
  };

  const switchPlayerSect = (sectId) => {
    if ((sectPlayer.sectResources?.reputation || 0) < SECT_SWITCH_REP_COST) {
      showMapToast('❌', '声望不足', `更换门派需要 ${SECT_SWITCH_REP_COST} 声望`, 2000); return;
    }
    setSectPlayer(prev => {
      const newRep = prev.sectResources.reputation - SECT_SWITCH_REP_COST;
      const newSectArts = (prev.sectMartialArts || []).filter(artId => {
        const art = getSectMartialArts(sectId).find(a => a.id === artId);
        return !!art;
      });
      return {
        ...prev,
        playerSect: sectId,
        playerSubSect: null,
        sectResources: { ...prev.sectResources, reputation: Math.max(0, newRep) },
        sectMartialArts: newSectArts,
        sectRank: getSectRankByRep(Math.max(0, newRep)),
        sectXinfaLevels: { ...prev.sectXinfaLevels, [sectId]: Math.max(1, prev.sectXinfaLevels?.[sectId] || 1) },
      };
    });
    showMapToast('🔄', '改换门庭', `你已改修【${SECT_DB[sectId]?.name}】，旧门派武学已清除`, 3000);
  };

  const setPlayerSubSectFn = (sectId) => {
    if ((sectPlayer.sectRank || 0) < SECT_SUB_SECT_REQ_RANK) {
      showMapToast('🔒', '未解锁', `身份达到【${SECT_RANKS[4]?.name}】后可副修`, 2500); return;
    }
    if (sectId === sectPlayer.playerSect) { showMapToast('⚠️', '提示', '不能与主修门派相同', 1500); return; }
    setSectPlayer(prev => ({ ...prev, playerSubSect: sectId }));
    showMapToast('📜', '副修门派', `副修【${SECT_DB[sectId]?.name}】（获得50%效果）`, 2500);
  };

  const upgradePlayerXinfa = (sectId) => {
    const cur = sectPlayer.sectXinfaLevels?.[sectId] || 1;
    if (cur >= 3) { showMapToast('✅', '已满级', '心法已达高阶', 1500); return; }
    const nextTier = cur + 1;
    const tierDef = SECT_XINFA[sectId]?.tiers?.find(t => t.tier === nextTier);
    if (!tierDef) return;
    if ((sectPlayer.sectRank || 0) < (tierDef.needRank || 1)) {
      showMapToast('🔒', '身份不足', `需要${getSectRankInfo(tierDef.needRank)?.name}`, 2000); return;
    }
    if ((sectPlayer.sectResources?.qiEssence || 0) < tierDef.qiCost) {
      showMapToast('❌', '真气不足', `需要 ${tierDef.qiCost} 心法真气`, 2000); return;
    }
    const lockKey = `xinfa:${sectId}`;
    if (sectActionLocksRef.current.has(lockKey)) return;
    sectActionLocksRef.current.add(lockKey);
    let upgraded = false;
    flushSync(() => setSectPlayer(prev => {
      const latestTier = prev.sectXinfaLevels?.[sectId] || 1;
      if (latestTier !== cur || (prev.sectRank || 0) < (tierDef.needRank || 1)) return prev;
      const qiEssence = Math.max(0, Number(prev.sectResources?.qiEssence) || 0);
      if (qiEssence < tierDef.qiCost) return prev;
      upgraded = true;
      return {
        ...prev,
        sectXinfaLevels: { ...prev.sectXinfaLevels, [sectId]: nextTier },
        sectResources: { ...prev.sectResources, qiEssence: qiEssence - tierDef.qiCost },
      };
    }));
    sectActionLocksRef.current.delete(lockKey);
    if (!upgraded) { showMapToast('⚠️', '突破失败', '心法状态或资源已变化，请重试', 1800); return; }
    showMapToast('✨', '心法突破', `${SECT_XINFA[sectId]?.name} · ${tierDef.name}`, 2500);
  };

  const learnSectMartialArt = (artId) => {
    const art = getMartialArtById(artId);
    if (!art) return;
    if ((sectPlayer.sectMartialArts || []).includes(artId)) {
      showMapToast('✅', '已学会', '你已经领悟此武学', 1500); return;
    }
    if ((sectPlayer.sectRank || 0) < art.needRank) {
      showMapToast('🔒', '身份不足', `需要${getSectRankInfo(art.needRank)?.name}`, 2000); return;
    }
    if (art.needTrial && !(sectPlayer.sectChiefTrials || []).includes(art.sectId)) {
      showMapToast('🔒', '需试炼', '完成掌门试炼后方可领悟镇派绝学', 2500); return;
    }
    if ((sectPlayer.sectResources?.scrollPage || 0) < (art.scrollCost || 0)) {
      showMapToast('❌', '残页不足', `需要 ${art.scrollCost} 武学残页`, 2000); return;
    }
    const lockKey = `martial:${artId}`;
    if (sectActionLocksRef.current.has(lockKey)) return;
    sectActionLocksRef.current.add(lockKey);
    let learned = false;
    flushSync(() => setSectPlayer(prev => {
      const scrollCost = Math.max(0, Number(art.scrollCost) || 0);
      const scrollPage = Math.max(0, Number(prev.sectResources?.scrollPage) || 0);
      if ((prev.sectMartialArts || []).includes(artId) || (prev.sectRank || 0) < art.needRank || scrollPage < scrollCost) return prev;
      if (art.needTrial && !(prev.sectChiefTrials || []).includes(art.sectId)) return prev;
      learned = true;
      return {
        ...prev,
        sectMartialArts: [...(prev.sectMartialArts || []), artId],
        sectResources: { ...prev.sectResources, scrollPage: scrollPage - scrollCost },
      };
    }));
    sectActionLocksRef.current.delete(lockKey);
    if (!learned) { showMapToast('⚠️', '领悟失败', '武学状态或资源已变化，请重试', 1800); return; }
    showMapToast('📖', '领悟武学', `学会【${art.name}】`, 2500);
  };

  const buyFromSectShop = (item) => {
    const cost = item.cost || 0;
    const resKey = item.resource || 'contribution';
    if ((sectPlayer.sectRank || 0) < (item.needRank || 0)) {
      showMapToast('🔒', '身份不足', `需要更高门派身份`, 2000); return;
    }
    if ((sectPlayer.sectResources?.[resKey] || 0) < cost) {
      showMapToast('❌', '不足', `${SECT_RESOURCE_LABELS[resKey] || resKey}不足`, 2000); return;
    }
    if (item.dailyLimit) {
      const today = getLocalDateStr();
      const bought = sectPlayer._shopPurchases?.[today]?.[item.id] || 0;
      if (bought >= item.dailyLimit) {
        showMapToast('❌', '限购', '今日已购买此物品', 2000); return;
      }
    }
    const lockKey = `shop:${item.id}`;
    if (sectActionLocksRef.current.has(lockKey)) return;
    sectActionLocksRef.current.add(lockKey);
    let purchased = false;
    flushSync(() => setSectPlayer(prev => {
      const today = getLocalDateStr();
      const currentResource = Math.max(0, Number(prev.sectResources?.[resKey]) || 0);
      const bought = prev._shopPurchases?.[today]?.[item.id] || 0;
      if ((prev.sectRank || 0) < (item.needRank || 0) || currentResource < cost) return prev;
      if (item.dailyLimit && bought >= item.dailyLimit) return prev;
      const sectResources = { ...prev.sectResources, [resKey]: currentResource - cost };
      if (item.grant) Object.entries(item.grant).forEach(([k, v]) => { sectResources[k] = (sectResources[k] || 0) + v; });
      const reputation = sectResources.reputation || 0;
      const shopPurchases = { ...(prev._shopPurchases || {}) };
      if (item.dailyLimit) {
        shopPurchases[today] = { ...(shopPurchases[today] || {}), [item.id]: bought + 1 };
      }
      purchased = true;
      return { ...prev, sectResources, sectRank: getSectRankByRep(reputation), _shopPurchases: shopPurchases };
    }));
    sectActionLocksRef.current.delete(lockKey);
    if (!purchased) { showMapToast('⚠️', '兑换失败', '库存、限购或资源状态已变化', 1800); return; }
    if (item.balls) setInventory(prev => ({ ...prev, balls: { ...prev.balls, ...Object.fromEntries(Object.entries(item.balls).map(([k, v]) => [k, (prev.balls?.[k] || 0) + v])) } }));
    if (item.itemGrant) setInventory(prev => ({ ...prev, misc: { ...prev.misc, [item.itemGrant]: (prev.misc?.[item.itemGrant] || 0) + (item.itemGrantCount || 1) } }));
    if (sectPlayer?.playerSect) advanceSectDaily('sect_contrib', cost);
    showMapToast('🛒', '兑换成功', item.name, 2000);
  };

  const advanceSectDaily = (taskId, amount = 1) => {
    const today = getLocalDateStr();
    setSectPlayer(prev => {
      const previousTodayTasks = prev.sectDailyDate === today ? (prev.sectDailyTasks || []) : [];
      let tasks = prev.sectDailyDate === today
        ? repairSectDailyTasks(previousTodayTasks, today, prev.playerSect)
        : generateSectDailyTasks(today, prev.playerSect);
      tasks = tasks.map(t => {
        if (t.id !== taskId || t.completed || t.date !== today) return t;
        const progress = Math.min(t.target, (t.progress || 0) + amount);
        const completed = progress >= t.target;
        return { ...t, progress, completed };
      });
      const previouslyCompleted = new Set(previousTodayTasks.filter(t => t.completed).map(t => `${t.date}:${t.id}`));
      const justCompleted = tasks.filter(t => t.completed && !previouslyCompleted.has(`${t.date}:${t.id}`));
      let sectResources = { ...prev.sectResources };
      justCompleted.forEach(t => {
        sectResources.reputation = (sectResources.reputation || 0) + (t.rep || 0);
        sectResources.contribution = (sectResources.contribution || 0) + (t.contrib || 0);
      });
      const next = { ...prev, sectDailyDate: today, sectDailyTasks: tasks, sectResources, sectRank: getSectRankByRep(sectResources.reputation || 0) };
      sectPlayerRef.current = next;
      return next;
    });
  };

  const claimAllSectDaily = () => {
    ensureSectDailyTasks();
    const tasks = sectPlayer.sectDailyTasks || [];
    const done = tasks.filter(t => t.completed).length;
    const total = tasks.length;
    if (!total) { showMapToast('📋', '日常', '今日任务尚未刷新', 1500); return; }
    showMapToast('📋', '日常进度', `已完成 ${done}/${total} 项（奖励在达成时自动发放）`, 2000);
  };

  const handleJianghuEventChoice = (eventId, choiceId) => {
    const evt = SECT_JIANGHU_EVENTS.find(e => e.id === eventId) || getActiveJianghuEvent();
    const choice = evt?.choices?.find(c => c.id === choiceId);
    if (!choice) return;
    const cycle = getSectEventCycleKey();
    const lockKey = `jianghu:${evt.id}:${cycle}`;
    if (sectActionLocksRef.current.has(lockKey)) return;
    sectActionLocksRef.current.add(lockKey);
    try {
      const currentSectPlayer = sectPlayerRef.current || sectPlayer;
      const alreadyChosen = (currentSectPlayer.sectEventLog || []).some(entry => entry.eventId === evt.id && entry.cycle === cycle);
      if (alreadyChosen) {
        showMapToast('ℹ️', '本周已选择', '江湖事件每个周期只能处理一次', 1800);
        return;
      }
      const repDelta = choice.rep || {};
      const penalty = choice.penalty || {};
      const sectResources = { ...(currentSectPlayer.sectResources || {}) };
      Object.entries(repDelta).forEach(([sid, v]) => {
        if (parseInt(sid, 10) === currentSectPlayer.playerSect) sectResources.reputation = (sectResources.reputation || 0) + v;
      });
      Object.entries(penalty).forEach(([sid, v]) => {
        if (parseInt(sid, 10) === currentSectPlayer.playerSect) sectResources.reputation = Math.max(0, (sectResources.reputation || 0) + v);
      });
      if (choice.grant) Object.entries(choice.grant).forEach(([k, v]) => { sectResources[k] = (sectResources[k] || 0) + v; });
      const nextSectPlayer = {
        ...currentSectPlayer,
        sectResources,
        sectRank: getSectRankByRep(sectResources.reputation || 0),
        sectEventLog: [...(currentSectPlayer.sectEventLog || []), { eventId: evt.id, choiceId, date: getLocalDateStr(), cycle }],
      };
      sectPlayerRef.current = nextSectPlayer;
      flushSync(() => setSectPlayer(nextSectPlayer));
      if (penalty.eco) {
        const ecoPenalty = Math.abs(Number(penalty.eco) || 0);
        applyMapEcologyDelta(currentMapId, { pollution: ecoPenalty, vegetation: -ecoPenalty });
      }
      showMapToast(evt.icon, evt.name, choice.label, 3000);
    } finally {
      window.setTimeout(() => sectActionLocksRef.current.delete(lockKey), 0);
    }
  };

  const changeSectFactionStance = (sectId, factionId) => {
    if ((sectPlayer.sectRank || 0) < 8) {
      showMapToast('🔒', '未解锁', '代掌门方可改变门派在国战中的立场', 2500); return;
    }
    setSectPlayer(prev => ({
      ...prev,
      sectStances: { ...prev.sectStances, [sectId]: factionId },
    }));
    showMapToast('🏳️', '立场变更', `${SECT_DB[sectId]?.name} 倾向 ${FACTIONS[factionId]?.fullName || factionId}`, 3000);
  };

  const startChiefTrial = (sectId) => {
    const currentSectPlayer = sectPlayerRef.current || sectPlayer;
    if ((currentSectPlayer.sectRank || 0) < 4) {
      showMapToast('🔒', '未解锁', '亲传弟子方可挑战掌门试炼', 2500); return;
    }
    if ((currentSectPlayer.sectResources?.masterToken || 0) < 1 && !(currentSectPlayer.sectChiefTrials || []).includes(sectId)) {
      showMapToast('🔒', '需掌门令', '门派商店可兑换掌门令', 2500); return;
    }
    const config = SECT_CHIEFS_CONFIG[sectId];
    const sectInfo = SECT_DB[sectId];
    if (!config) return;
    if ((partyRef.current || party).length < 3) { showMapToast('⚠️', '队伍不足', '掌门试炼需要至少3只精灵', 2000); return; }
    setConfirmModal({ title: '👑 掌门试炼', msg: `挑战【${sectInfo.name}】掌门幻影？`, onOk: () => {
      const lockKey = `chief:${sectId}`;
      if (sectActionLocksRef.current.has(lockKey) || battle) return;
      const latestParty = partyRef.current || party;
      const latestSectPlayer = sectPlayerRef.current || sectPlayer;
      const firstClear = !(latestSectPlayer.sectChiefTrials || []).includes(sectId);
      if (latestParty.length < 3) {
        showMapToast('⚠️', '队伍不足', '掌门试炼需要至少3只精灵', 1800);
        return;
      }
      if (firstClear && (latestSectPlayer.sectResources?.masterToken || 0) < 1) {
        showMapToast('🔒', '需掌门令', '掌门令已被使用，请重新兑换', 2200);
        return;
      }
      sectActionLocksRef.current.add(lockKey);
      let tokenReserved = false;
      if (firstClear) {
        const reservedState = {
          ...latestSectPlayer,
          sectResources: {
            ...(latestSectPlayer.sectResources || {}),
            masterToken: Math.max(0, (latestSectPlayer.sectResources?.masterToken || 0) - 1),
          },
        };
        tokenReserved = true;
        sectPlayerRef.current = reservedState;
        flushSync(() => setSectPlayer(reservedState));
      }
      const rollback = () => {
        if (tokenReserved) {
          const latest = sectPlayerRef.current || latestSectPlayer;
          const restored = {
            ...latest,
            sectResources: {
              ...(latest.sectResources || {}),
              masterToken: (latest.sectResources?.masterToken || 0) + 1,
            },
          };
          sectPlayerRef.current = restored;
          setSectPlayer(restored);
        }
        sectActionLocksRef.current.delete(lockKey);
      };
      const enemyParty = [];
      const teamIds = SECT_TEAMS[sectId] || [];
      const playerMaxLv = Math.max(...latestParty.map(p => p.level || 1));
      const baseLv = Math.min(100, Math.max(70, playerMaxLv + 10));
      teamIds.forEach((petId, idx) => {
        const pet = createPet(petId, idx === 0 ? Math.min(100, baseLv + 5) : baseLv, true, idx === 0);
        pet.sectId = parseInt(sectId, 10);
        pet.sectLevel = 10;
        pet.customStatMult = 1.2;
        if (idx === 0) pet.name = `[掌门] ${pet.name}`;
        enemyParty.push(pet);
      });
      const started = attemptBattleStart('掌门试炼', () => startBattle({
        id: 8100 + sectId,
        name: `${config.title}·掌门试炼`,
        customParty: enemyParty,
        drop: firstClear ? 15000 : 4000,
        _isChiefTrial: true,
        _chiefTrialSectId: sectId,
        _chiefTrialTokenReserved: tokenReserved,
      }, 'sect_challenge'), rollback);
      if (started) window.setTimeout(() => sectActionLocksRef.current.delete(lockKey), 0);
    }});
  };

  const startSectRealmFromHub = (realmId) => {
    const def = getSectRealmById(realmId);
    if (!def) return;
    if (badges.length < def.reqBadges) { showMapToast('🔒', '未解锁', `需要 ${def.reqBadges} 徽章`, 2000); return; }
    const currentParty = partyRef.current || party;
    const currentFusion = fusionStateRef.current || fusionState;
    const currentSectPlayer = sectPlayerRef.current || sectPlayer;
    const partySectIds = [...new Set(currentParty.map(p => p.sectId).filter(Boolean))];
    const available = getAvailableSectRealms(badges.length, partySectIds, currentFusion.sectRealmsCleared || []);
    if (!available.find(r => r.id === realmId)) {
      showMapToast('❌', '条件不足', '队伍需有对应门派精灵或已通关', 2500); return;
    }
    const stepIdx = Math.max(
      Number(currentFusion[`sect_progress_${realmId}`]) || 0,
      Number(currentSectPlayer.sectRealmProgress?.[realmId]) || 0,
    );
    const step = def.steps?.[stepIdx];
    if (!step) { showMapToast('✅', '已完成', '该秘境已通关', 1500); return; }
    if (step.type === 'puzzle' || step.type === 'explore' || step.type === 'soothe') {
      const lockKey = `realm-step:${realmId}:${stepIdx}`;
      if (sectActionLocksRef.current.has(lockKey)) return;
      const reqTypes = step.reqTypes || [];
      const hasType = currentParty.some(p => reqTypes.includes(p.type) || reqTypes.includes(p.type2));
      if (reqTypes.length && !hasType) {
        showMapToast('❌', '条件不足', `需要${reqTypes.join('/')}系精灵`, 2500); return;
      }
      const reqTags = step.reqTags || [];
      if (reqTags.length) {
        const hasTag = currentParty.some(p => { const tags = inferPetTags(p) || []; return reqTags.some(t => tags.includes(t)); });
        if (!hasTag) { showMapToast('❌', '条件不足', `需要具备${reqTags.join('/')}标签的精灵`, 2500); return; }
      }
      sectActionLocksRef.current.add(lockKey);
      try {
        const latestFusion = fusionStateRef.current || currentFusion;
        const latestSect = sectPlayerRef.current || currentSectPlayer;
        const authoritativeStep = Math.max(
          Number(latestFusion[`sect_progress_${realmId}`]) || 0,
          Number(latestSect.sectRealmProgress?.[realmId]) || 0,
        );
        if (authoritativeStep !== stepIdx) return;
        const nextStep = stepIdx + 1;
        commitFusionState(prev => ({ ...prev, [`sect_progress_${realmId}`]: nextStep }));
        const nextResources = {
          ...(latestSect.sectResources || {}),
          contribution: (latestSect.sectResources?.contribution || 0) + 20,
          reputation: (latestSect.sectResources?.reputation || 0) + 25,
        };
        const nextSect = {
          ...latestSect,
          sectRealmProgress: { ...(latestSect.sectRealmProgress || {}), [realmId]: nextStep },
          sectResources: nextResources,
          sectRank: getSectRankByRep(nextResources.reputation || 0),
        };
        sectPlayerRef.current = nextSect;
        flushSync(() => setSectPlayer(nextSect));
        if (nextStep >= def.steps.length) completeSectRealm(realmId, def);
        else showMapToast('✅', step.title, step.text, 3500);
      } finally {
        window.setTimeout(() => sectActionLocksRef.current.delete(lockKey), 0);
      }
      return;
    }
    const battleLockKey = `realm-battle:${realmId}:${stepIdx}`;
    if (sectActionLocksRef.current.has(battleLockKey) || battle) return;
    sectActionLocksRef.current.add(battleLockKey);
    const leadSect = currentParty[0]?.sectId;
    const chakraAffSR = calcChakraAffinity(narutoState?.jutsuMastery);
    const jutsuSynSR = chakraAffSR ? checkJutsuPetSynergy(currentParty, CHAKRA_NATURE_MAP[chakraAffSR]?.gameType) : null;
    const srFusionBonuses = mergePveBonuses(
      calcFusionPveBonuses({ sectId: leadSect, generalTacticId: fusionState.generalTacticId, jutsuSynergy: jutsuSynSR }),
      calcCrossSystemPveBonuses({ playerStyle: fusionState.playerStyle || {}, kwPosition: fusionState.kwPosition, nightBattle: !!(step.nightBattle || timePhase === 'NIGHT') })
    );
    const enemyParty = [];
    if (step.type === 'boss' || step.bossId) {
      const boss = createPet(step.bossId || 1, step.lvl || 55, true, true);
      boss.name = step.enemyName || boss.name;
      boss.customStatMult = (boss.customStatMult || 1) * Math.max(0.7, 1 - (srFusionBonuses.bossMultReduce || 0));
      enemyParty.push(boss);
    } else {
      const pool = step.pool || [1];
      const lvl = step.lvl || [40, 50];
      const count = step.count || 2;
      for (let i = 0; i < count; i++) enemyParty.push(createPet(pool[Math.floor(Math.random() * pool.length)], _.random(lvl[0], lvl[1]), true));
    }
    const srProtectBase = Math.floor(getStats(currentParty[0] || {}).maxHp * (0.6 + (srFusionBonuses.protectBonus || 0)));
    const objTurns = step.objectiveTurns ? Math.max(3, (step.objectiveTurns || 8) - (srFusionBonuses.escapeTurnReduce || 0)) : undefined;
    const latestStep = Math.max(
      Number(fusionStateRef.current?.[`sect_progress_${realmId}`]) || 0,
      Number(sectPlayerRef.current?.sectRealmProgress?.[realmId]) || 0,
    );
    if (latestStep !== stepIdx) {
      sectActionLocksRef.current.delete(battleLockKey);
      return;
    }
    const started = attemptBattleStart('门派秘境', () => startBattle({
      id: def.mapId || currentMapId,
      name: def.name,
      customParty: enemyParty,
      trainerName: step.enemyName || def.name,
      drop: step.drop ?? 3000,
      _fusionBonuses: srFusionBonuses,
      _sectRealm: { realmId, stepIdx },
      ...(step.objective ? {
        battleObjective: step.objective,
        objectiveTurns: objTurns,
        _purifyProgress: step.objective === 'purify' ? 100 : undefined,
        _protectHp: step.objective === 'protect' ? srProtectBase : undefined,
        _protectMaxHp: step.objective === 'protect' ? srProtectBase : undefined,
      } : {}),
    }, 'sect_realm'), () => sectActionLocksRef.current.delete(battleLockKey));
    if (started) window.setTimeout(() => sectActionLocksRef.current.delete(battleLockKey), 0);
  };

  const completeSectRealm = (realmId, def) => {
    const lockKey = `realm-complete:${realmId}`;
    if (sectRealmCompletionLocksRef.current.has(lockKey)) return;
    if ((fusionStateRef.current?.sectRealmsCleared || []).includes(realmId)) return;
    sectRealmCompletionLocksRef.current.add(lockKey);
    commitFusionState(prev => ({
      ...prev,
      sectRealmsCleared: [...new Set([...(prev.sectRealmsCleared || []), realmId])],
      [`sect_progress_${realmId}`]: def.steps?.length || prev[`sect_progress_${realmId}`] || 0,
    }));
    const r = def.reward || {};
    if (r.gold) {
      goldRef.current += r.gold;
      setGold(goldRef.current);
      updateAchStat({ totalGoldEarned: r.gold });
    }
    if (r.title) unlockTitle(r.title);
    if (r.generalFragment) {
      commitFusionState(prev => ({ ...prev, generalFragments: { ...(prev.generalFragments || {}), [r.generalFragment]: ((prev.generalFragments || {})[r.generalFragment] || 0) + 1 } }));
      showMapToast('🎖️', '名将碎片', `获得 ${r.generalFragment} 碎片 ×1`, 2500);
    }
    const finalArt = getSectMartialArts(def.sectIds?.[0]).find(a => a.tier === 'final');
    const latestSect = sectPlayerRef.current || sectPlayer;
    const nextResources = {
      ...(latestSect.sectResources || {}),
      contribution: (latestSect.sectResources?.contribution || 0) + (r.sectContrib || 50),
      scrollPage: (latestSect.sectResources?.scrollPage || 0) + (r.scrollPage || 0),
      reputation: (latestSect.sectResources?.reputation || 0) + 80,
    };
    const shouldLearnFinal = finalArt && latestSect.playerSect === def.sectIds?.[0];
    const nextSect = {
      ...latestSect,
      sectRealmProgress: { ...(latestSect.sectRealmProgress || {}), [realmId]: def.steps?.length || 0 },
      sectResources: nextResources,
      sectRank: getSectRankByRep(nextResources.reputation || 0),
      sectMartialArts: shouldLearnFinal && !(latestSect.sectMartialArts || []).includes(finalArt.id)
        ? [...(latestSect.sectMartialArts || []), finalArt.id]
        : (latestSect.sectMartialArts || []),
    };
    sectPlayerRef.current = nextSect;
    setSectPlayer(nextSect);
    updateAchStat({ fusionDungeonsCleared: 1 });
    showMapToast(def.icon, '秘境通关', `${def.name} — ${r.title || '奖励已发放'}`, 4000);
  };

   // ==========================================
  // [完整版] 门派顶峰界面 (含阵容预览与点击交互)
