  const renderSectSummit = () => <SectSummitScreen {...{ badges, buyFromSectShop, changeSectFactionStance, claimAllSectDaily, currentTitle, fusionState, getSectEventCycleKey, handleJianghuEventChoice, joinPlayerSect, kingdomWar, learnSectMartialArt, openSectTeamDetail, party, safeBack, sectHubTab, sectJoinFocus, sectPlayer, sectTitles, setCurrentTitle, setPlayerSubSectFn, setSectHubTab, setSectJoinFocus, setView, showMapToast, startChiefTrial, startSectChallenge, startSectRealmFromHub, switchPlayerSect, upgradePlayerXinfa }} />;

