    // ==========================================
  // [修复] 剧情对话框组件 (解决跳过战斗问题)
  // ==========================================
  const renderDialogOverlay = () => {
    if (!isDialogVisible || dialogQueue.length === 0) return null;

    const safeIdx = Math.min(currentDialogIndex, dialogQueue.length - 1);
    const currentLine = dialogQueue[safeIdx];
    if (!currentLine) return null;
    const isLastLine = safeIdx === dialogQueue.length - 1;

    const handleNext = () => {
      if (isLastLine) {
        // 1. 关闭对话框
        setIsDialogVisible(false);
        setDialogQueue([]);
        setCurrentDialogIndex(0);

        // 2. 处理挂起任务 (如战斗)
        if (pendingTask) {
           if (pendingTask.type === 'battle') {
              startBattle({ 
                id: 999, 
                name: pendingTask.name, 
                pool: [pendingTask.enemyId],
                eliteParty: pendingTask.eliteParty || null,
                storyTaskStep: pendingTask.step,
                storyTaskX: pendingTask.x,
                storyTaskY: pendingTask.y,
                mustLose: !!pendingTask.mustLose,
                defeatAdvances: !!pendingTask.defeatAdvances,
                scriptedDefeat: !!pendingTask.scriptedDefeat,
                storyOutcome: pendingTask.outcome,
              }, 'story_task');
              
              setPendingTask(null);
              return; 
           } else {
              const nextStep = pendingTask.step + 1;
              setStoryStep(nextStep);
              // debug: Dialog task advancing
              
              const currentChapter = STORY_SCRIPT[storyProgress];
              const nextTask = currentChapter?.tasks?.find(t => t.step === nextStep);
              if(nextTask) {
                  setMapGrid(prev => {
                      const newGrid = prev.map(row => [...row]);
                      if(newGrid[nextTask.y]) newGrid[nextTask.y][nextTask.x] = 99;
                      return newGrid;
                  });
                  showMapToast('📍', '剧情推进', `下一目标: ${nextTask.name} (${nextTask.x},${nextTask.y}) ${nextTask.type === 'battle' ? '⚔️' : '💬'}`, 3000);
              } else {
                  showMapToast('🎉', '剧情完成', '本章剧情任务全部完成！现在可以去挑战道馆馆主了！', 3000);
              }
           }
           setPendingTask(null);
        }
        
        
      } else {
        setCurrentDialogIndex(prev => prev + 1);
      }
    };
    dialogNextRef.current = handleNext;

    return (
      <>
        <div style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.45)',zIndex:2999,pointerEvents:'auto'}} onClick={handleNext}/>
        <div className="dialog-overlay" onClick={handleNext}>
          <div className="dialog-box">
            <div className="dialog-header" style={{display:'flex',alignItems:'center',gap:'6px'}}>
               {currentLine.icon && <span style={{fontSize:'18px'}}>{currentLine.icon}</span>}
               {!currentLine.icon && <span style={{background:'linear-gradient(135deg,#667eea,#764ba2)',borderRadius:'50%',width:'22px',height:'22px',display:'inline-flex',alignItems:'center',justifyContent:'center',color:'#fff',fontSize:'10px',fontWeight:'bold'}}>{(currentLine.name||'?')[0]}</span>}
               <span className="dialog-name">{currentLine.name}</span>
            </div>
            <div className="dialog-text">{currentLine.text}</div>
            <div className="dialog-hint">▼ 点击或按空格键继续 {!isLastLine ? `(${currentDialogIndex+1}/${dialogQueue.length})` : '(完)'}</div>
          </div>
        </div>
      </>
    );
  };

 const getMoveCategory = (type, move = null) => {
    if (move && move.category) return move.category;
    if (move && move.cat) return move.cat;
    const physicalTypes = ['NORMAL', 'FIGHT', 'FLYING', 'GROUND', 'ROCK', 'BUG', 'GHOST', 'STEEL'];
    return physicalTypes.includes(type) ? 'physical' : 'special';
  };
  
  const handleItemUseOnPet = (petIdx) => {
    if (!usingItem) return;
    const actionItem = usingItem;
    const lockKey = `team-item:${actionItem.category}:${actionItem.id}`;
    if (inventoryActionLocksRef.current.has(lockKey)) return;
    inventoryActionLocksRef.current.add(lockKey);
    try {
    const currentInventory = inventoryRef.current || inventory;
    const currentParty = partyRef.current || [];
    const newParty = currentParty.map(member => ({
      ...member,
      moves: (member.moves || []).map(move => ({ ...move })),
      ivs: member.ivs ? { ...member.ivs } : member.ivs,
      evs: member.evs ? { ...member.evs } : member.evs,
    }));
    const pet = newParty[petIdx];
    const evolutionReadyBeforeUse = Boolean(pet?.canEvolve);
    if (!pet) { showMapToast('❌', '提示', '无效的精灵序号！', 1500); return; }
    const stats = getStats(pet);
    let consumed = false;
    let msg = "";
    let nextInventory = currentInventory;

    const currentStack = actionItem.category === 'meds'
      ? ((currentInventory.meds || {})[actionItem.id] || 0)
      : actionItem.category === 'berry'
        ? (normalizeBerriesInventory(currentInventory.berries)[actionItem.id] || 0)
        : actionItem.category === 'tm'
          ? ((currentInventory.tms || {})[actionItem.id] || 0)
          : actionItem.category === 'stone'
            ? ((currentInventory.stones || {})[actionItem.id] || 0)
            : actionItem.category === 'growth'
              ? (currentInventory[actionItem.id] || 0)
              : 0;
    if (currentStack <= 0) {
      showMapToast('📦', '道具不足', '该道具库存已经变化', 1600);
      setUsingItem(null);
      return;
    }

    // --- 进化石逻辑 (保持不变) ---
        // ... 在 handleItemUseOnPet 函数内部 ...
    // --- 进化石逻辑 ---
    if (usingItem.category === 'stone') {
        const stoneId = usingItem.id;
        if (pet.isFusion) { showMapToast('❌', '提示', '融合精灵无法使用进化石！', 1500); return; }
        const rules = STONE_EVO_RULES[pet.id];
        
        if (rules && rules[stoneId]) {
            const targetId = rules[stoneId];
            const targetPetInfo = POKEDEX.find(p => p.id === targetId);
            
            if (targetPetInfo) {
                const srcPetInfo = POKEDEX.find(p => p.id === pet.id);
                const stoneEvoCond = srcPetInfo?.evoCondition || targetPetInfo.evoCondition;
                if (stoneEvoCond && !checkEvoCondition(pet, targetPetInfo, { allowItem: true, itemId: stoneId })) {
                    const cond = stoneEvoCond;
                    const hint = cond.time ? `需要在${cond.time.toUpperCase() === 'NIGHT' ? '夜晚' : '白天'}` : cond.intimacy ? `亲密度需≥${cond.intimacy}` : '条件不满足';
                    showMapToast('❌', '进化条件不足', hint, 2000);
                    return;
                }
                const petUid = pet.uid;
                setConfirmModal({ title:'🔮 进化确认', msg:`确认使用 ${usingItem.name || '进化石'} 将 ${pet.name} 进化为 ${targetPetInfo.name}？\n此操作不可撤销！`, onOk: () => {
                const confirmLockKey = `stone-evolve:${stoneId}:${petUid}`;
                if (inventoryActionLocksRef.current.has(confirmLockKey)) return;
                inventoryActionLocksRef.current.add(confirmLockKey);
                try {
                const latestInventory = inventoryRef.current || inventory;
                const latestParty = partyRef.current || [];
                const latestIdx = latestParty.findIndex(currentPet => currentPet.uid === petUid);
                const latestPet = latestParty[latestIdx];
                if (!latestPet || ((latestInventory.stones || {})[stoneId] || 0) <= 0 || STONE_EVO_RULES[latestPet.id]?.[stoneId] !== targetId) {
                  showMapToast('ℹ️', '进化取消', '精灵状态或进化石库存已经变化', 2000);
                  return;
                }
                const confirmedInventory = { ...latestInventory, stones: { ...(latestInventory.stones || {}), [stoneId]: latestInventory.stones[stoneId] - 1 } };
                inventoryRef.current = confirmedInventory;
                setInventory(confirmedInventory);
                const usedStonesList = [...new Set([...(achStatsRef.current.usedStonesList || []), stoneId])];
                updateAchStat({ usedStonesList, uniqueStonesUsed: usedStonesList.length });
                
                beginEvolution({
                    targetIdx: latestIdx,
                    oldPet: latestPet,
                    newPet: targetPetInfo,
                    step: 0
                });
                
                setUsingItem(null);
                setTeamMode(false); 
                } finally {
                  window.setTimeout(() => inventoryActionLocksRef.current.delete(confirmLockKey), 0);
                }
                }});
                return; 
            }
        } else {
            showMapToast('ℹ️', '提示', '它似乎不喜欢这个石头。', 2000);
            return;
        }
    }

    // --- 药品逻辑 (修改部分) ---
    if (usingItem.category === 'meds') {
        const med = usingItem.data;
        if (!med || !med.type) { showMapToast('❌', '提示', '该物品数据异常，无法使用。', 1500); return; }
        if (med.type === 'REVIVE') {
            if (pet.currentHp > 0) { showMapToast('ℹ️', '提示', '它还很精神呢，不需要复活！', 2000); return; }
            const healAmt = Math.floor(stats.maxHp * med.val);
            pet.currentHp = healAmt;
            consumed = true;
            msg = `${pet.name} 复活了！恢复了 ${healAmt} 点体力！`;
        }
        else if (med.type === 'REVIVE_ALL') {
            let any = false;
            newParty.forEach((pn) => {
                if (pn.currentHp <= 0) {
                    const st = getStats(pn);
                    pn.currentHp = st.maxHp;
                    pn.status = null;
                    any = true;
                }
            });
            if (!any) { showMapToast('❌', '提示', '没有濒死的精灵。', 1500); return; }
            consumed = true;
            msg = '全队复活并恢复满体力！';
        }
        else if (med.type === 'FULL_RESTORE') {
            if (pet.currentHp <= 0) { showMapToast('❌', '提示', '濒死精灵请先用复活药。', 1500); return; }
            const hasMissingPp = (pet.moves || []).some(move => (move.pp || 0) < (move.maxPP || 15));
            if (pet.currentHp >= stats.maxHp && !pet.status && !(med.id === 'max_elixir' && hasMissingPp)) {
              showMapToast('ℹ️', '提示', '体力与状态已经恢复，无需使用。', 1500); return;
            }
            pet.currentHp = stats.maxHp;
            pet.status = null;
            if (med.id === 'max_elixir') {
                (pet.moves || []).forEach(m => { m.pp = m.maxPP || m.pp; });
                msg = '体力、异常与技能PP全部恢复！';
            } else {
                msg = '体力与异常状态全部恢复！';
            }
            consumed = true;
        }
        else if (med.type === 'BUFF') {
            showMapToast('ℹ️', '提示', '能力强化类药品仅可在战斗中使用。', 2000);
            return;
        }
        // 普通药
        else {
            if (pet.currentHp <= 0) { showMapToast('❌', '提示', '它已经晕厥了，无法使用这个药物！ 请使用【活力块】或【活力星】。', 1500); return; }
            
            if (med.type === 'HP') {
                if (pet.currentHp >= stats.maxHp) { showMapToast('❌', '提示', '体力已满！', 1500); return; }
                const heal = med.val === 9999 ? stats.maxHp : med.val;
                pet.currentHp = Math.min(stats.maxHp, pet.currentHp + heal);
                consumed = true;
                msg = `恢复了体力！`;
            } else if (med.type === 'PP') {
                const moves = pet.moves || [];
                const low = moves.filter(m => (m.pp || 0) < (m.maxPP || 15)).sort((a, b) => (a.pp || 0) - (b.pp || 0))[0];
                if (low) {
                    low.pp = Math.min(low.maxPP || 15, (low.pp || 0) + (med.val || 10));
                    consumed = true;
                    msg = `${low.name} 的PP恢复了！`;
                } else {
                    showMapToast('❌', '提示', '技能PP已满。', 1500);
                    return;
                }
            } else if (med.type === 'PP_ALL') {
                 const allFull = (pet.moves || []).every(m => (m.pp || 0) >= (m.maxPP || 15));
                 if (allFull) { showMapToast('⚠️', '提示', '所有技能PP已满。', 1500); return; }
                 (pet.moves || []).forEach(m => { m.pp = Math.min(m.maxPP || 15, (m.pp || 0) + (med.val || 10)); });
                 consumed = true;
                 msg = `技能 PP 已恢复！`;
            } else if (med.type === 'STATUS') {
                 if(pet.status && (med.val === 'ALL' || pet.status === med.val)) {
                     pet.status = null;
                     consumed = true;
                     msg = `异常状态已治愈！`;
                 } else {
                     showMapToast('❌', '提示', pet.status ? '该药品对当前异常状态无效。' : '它很健康，没有异常状态。', 1500);
                     return;
                 }
            } else {
                 showMapToast('❌', '提示', '该药物暂无效果或不适用。', 1500);
                 return;
            }
        }
        
        if (consumed) {
            nextInventory = { ...nextInventory, meds: { ...(nextInventory.meds || {}), [med.id]: nextInventory.meds[med.id] - 1 } };
            pet.intimacy = Math.min(255, (pet.intimacy || 0) + 2);
            msg += ` (亲密度 +2)`;
        }
    }
    else if (usingItem.category === 'berry') {
        const berry = usingItem.data;
        if (!berry || !berry.id) { showMapToast('❌', '提示', '树果数据异常。', 1500); return; }
        const have = normalizeBerriesInventory(currentInventory.berries)[berry.id] || 0;
        if (have <= 0) return;
        if (pet.currentHp <= 0) { showMapToast('❌', '提示', '濒死精灵请先用复活药。', 1500); return; }
        if (pet.equippedBerry === berry.id) { showMapToast('ℹ️', '提示', `${pet.name} 已经装备了这个树果`, 1500); return; }
        let nextBerries = addBerries(currentInventory.berries, berry.id, -1);
        if (pet.equippedBerry && BERRIES[pet.equippedBerry]) nextBerries = addBerries(nextBerries, pet.equippedBerry, 1);
        pet.equippedBerry = berry.id;
        consumed = true;
        nextInventory = { ...nextInventory, berries: nextBerries };
        pet.intimacy = Math.min(255, (pet.intimacy || 0) + 1);
        msg = `${pet.name} 装备了 ${berry.name}（战斗中自动触发，触发后消耗）`;
    }
    // --- 技能书 (TM) ---
    else if (usingItem.category === 'tm') {
        if (pet.currentHp <= 0) { showMapToast('❌', '提示', '晕厥的精灵无法学习技能！', 1500); return; }
        const tm = usingItem.data;
        if (!tm) { showMapToast('❌', '提示', '技能书数据异常！', 1500); return; }
        const tmPetTypes = [pet.type, pet.secondaryType].filter(Boolean);
        if (!tmPetTypes.includes(tm.type) && tm.type !== 'NORMAL') {
            showMapToast('❌', '无法学习', '属性不匹配', 1500); return;
        }
        if ((pet.moves || []).some(m => m.name === tm.name)) {
            showMapToast('⚠️', '无法学习', '已经学会了该技能', 1500); return;
        }
        const newMove = buildMoveFromTm(tm);
        if ((pet.moves || []).length < 4) {
            pet.moves.push(newMove);
            consumed = true;
            msg = `📖 ${pet.name} 学会了 [${tm.name}]!`;
            advanceBounty('learn_tm');
            nextInventory = { ...nextInventory, tms: { ...(nextInventory.tms || {}), [tm.id]: nextInventory.tms[tm.id] - 1 } };
        } else {
            newMove._tmId = tm.id;
            pet.pendingLearnMove = newMove;
            partyRef.current = newParty;
            setParty(newParty);
            setLearningPetIdx(petIdx);
            setPendingMove(newMove);
            setUsingItem(null);
            setView('move_forget');
            return;
        }
    }
    // --- 属性增强 ---
    else if (usingItem.category === 'growth') {
        if (pet.currentHp <= 0) { showMapToast('❌', '提示', '晕厥的精灵无法使用！', 1500); return; }
        const item = usingItem.data;
        if (!item) { showMapToast('❌', '提示', '道具数据异常！', 1500); return; }
      
        if (item.id === 'max_candy') {
            if (pet.level >= 100) { showMapToast('ℹ️', '提示', '它已经达到等级上限了！', 2000); return; }
            if (badges.length < 8) { showMapToast('🔒', '徽章不足', '神奇糖果需要 8 枚徽章后才能使用。', 2200); return; }
            if ((currentInventory[item.id] || 0) <= 0) { showMapToast('❌', '提示', '道具数量不足！', 1500); return; }
            const oldLv = pet.level;
            pet.level = getGrowthItemTargetLevel(pet.level, item);
            pet.exp = 0;
            pet.nextExp = pet.level >= 100 ? 999999 : calcNextExp(pet.level, NATURE_DB[pet.nature]?.exp || 1.0); 
            
            const dex = POKEDEX.find(p => p.id === pet.id);
            if (dex?.learnset) {
              for (let lv = oldLv + 1; lv <= pet.level; lv++) {
                const learn = dex.learnset.filter(ls => ls.level === lv);
                learn.forEach(ls => {
                  const move = allSkills.find(s => s.id === ls.move);
                  if (move) {
                    const offered = offerMoveToPet(pet, move);
                    Object.assign(pet, offered.pet);
                  }
                });
              }
            }

            const newStats = getStats(pet);
            pet.currentHp = newStats.maxHp; 

            Object.assign(pet, refreshPetEvolution(pet, POKEDEX, { timePhase, weather }));
            consumed = true;
            msg = `不可思议！${pet.name} 提升了 ${pet.level - oldLv} 级，现在是 Lv.${pet.level}！${pet.canEvolve ? '（✨可以进化了）' : ''}`;
            nextInventory = { ...nextInventory, [item.id]: nextInventory[item.id] - 1 };
        } else if (item.id === 'exp_candy') {
            if (pet.level >= 100) { showMapToast('ℹ️', '提示', '它已经达到等级上限了！', 2000); return; }
            if ((currentInventory.exp_candy || 0) <= 0) { showMapToast('❌', '提示', '道具数量不足！', 1500); return; }

            const candyCount = currentInventory.exp_candy || 0;
            const maxLevels = Math.min(candyCount, 100 - pet.level);
            if (usingItem.batch && maxLevels > 1) {
                const targetLvOptions = [];
                for (let n = 5; n <= maxLevels; n += 5) targetLvOptions.push(n);
                if (maxLevels > 0 && !targetLvOptions.includes(maxLevels)) targetLvOptions.push(maxLevels);
                const targetLv = Math.min(pet.level + maxLevels, 100);
                const petUid = pet.uid;
                setConfirmModal({ title: '🍬 批量使用经验糖果', msg: `将 ${pet.name} (Lv.${pet.level}) 一次性升到 Lv.${targetLv}？\n消耗经验糖果 x${targetLv - pet.level}`, onOk: () => {
                    const confirmLockKey = `batch-candy:${petUid}`;
                    if (inventoryActionLocksRef.current.has(confirmLockKey)) return;
                    inventoryActionLocksRef.current.add(confirmLockKey);
                    try {
                    const latestParty = partyRef.current || [];
                    const latestInventory = inventoryRef.current || inventory;
                    const latestIdx = latestParty.findIndex(currentPet => currentPet.uid === petUid);
                    const latestPet = latestParty[latestIdx];
                    const availableCandy = latestInventory.exp_candy || 0;
                    if (!latestPet || latestPet.currentHp <= 0 || availableCandy <= 0 || latestPet.level >= 100) {
                      showMapToast('ℹ️', '批量升级取消', '精灵状态或糖果库存已经变化', 2000);
                      return;
                    }
                    const confirmedTargetLv = Math.min(targetLv, latestPet.level + availableCandy, 100);
                    const usedCount = confirmedTargetLv - latestPet.level;
                    if (usedCount <= 0) return;
                    const np = [...latestParty];
                    const p = {
                      ...latestPet,
                      moves: (latestPet.moves || []).map(move => ({ ...move })),
                      ivs: latestPet.ivs ? { ...latestPet.ivs } : latestPet.ivs,
                      evs: latestPet.evs ? { ...latestPet.evs } : latestPet.evs,
                    };
                    np[latestIdx] = p;
                    const oldLv = p.level;
                    p.level = confirmedTargetLv;
                    p.exp = 0;
                    p.nextExp = p.level >= 100
                      ? 999999
                      : calcNextExp(p.level, NATURE_DB[p.nature || 'docile']?.exp || 1.0);
                    const oldMaxHp = getStats({...p, level: oldLv}).maxHp;
                    const ns = getStats(p);
                    const hpDiff = Math.max(0, ns.maxHp - oldMaxHp);
                    p.currentHp = Math.min(ns.maxHp, p.currentHp + hpDiff);
                    const pokedex2 = POKEDEX.find(px => px.id === p.id);
                    if (pokedex2?.learnset) {
                        for (let lv = oldLv + 1; lv <= p.level; lv++) {
                            const learn = pokedex2.learnset.filter(ls => ls.level === lv);
                            learn.forEach(ls => {
                                const move = allSkills.find(s => s.id === ls.move);
                                if (move) {
                                    const offered = offerMoveToPet(p, move);
                                    Object.assign(p, offered.pet);
                                }
                            });
                        }
                    }
                    const intimacyGain = usedCount * 3;
                    p.intimacy = Math.min(255, (p.intimacy || 0) + intimacyGain);
                    const refreshedPet = refreshPetEvolution(p, POKEDEX, { timePhase, weather });
                    np[latestIdx] = refreshedPet;
                    const confirmedInventory = { ...latestInventory, exp_candy: availableCandy - usedCount };
                    partyRef.current = np;
                    inventoryRef.current = confirmedInventory;
                    flushSync(() => { setParty(np); setInventory(confirmedInventory); });
                    if (marriageRef.current?.pendingPropose) updateQuestProgress(marriageRef.current.pendingPropose, 'level_up', usedCount);
                    const evolutionHint = refreshedPet.canEvolve ? '，并出现了进化征兆' : '';
                    showMapToast('🍬', '批量升级', `${refreshedPet.name} Lv.${oldLv} → Lv.${refreshedPet.level}${evolutionHint}（糖果x${usedCount}，亲密度+${intimacyGain}）`, 3000);
                    setUsingItem(null);
                    if (refreshedPet.pendingLearnMove) {
                      setLearningPetIdx(latestIdx);
                      setPendingMove(refreshedPet.pendingLearnMove);
                      setView('move_forget');
                    } else {
                      setView('bag');
                    }
                    } finally {
                      window.setTimeout(() => inventoryActionLocksRef.current.delete(confirmLockKey), 0);
                    }
                }});
                return;
            }

            const oldLv = pet.level;
            pet.level = getGrowthItemTargetLevel(pet.level, item);
            pet.exp = 0;
            pet.nextExp = pet.level >= 100
              ? 999999
              : calcNextExp(pet.level, NATURE_DB[pet.nature || 'docile']?.exp || 1.0);

            const newStats = getStats(pet);
            const hpDiff = newStats.maxHp - getStats({...pet, level: oldLv}).maxHp;
            pet.currentHp = Math.min(newStats.maxHp, pet.currentHp + Math.max(0, hpDiff));
            // 升级学技能
            const lsData = POKEDEX.find(p => p.id === pet.id);
            if (lsData?.learnset) {
              lsData.learnset.filter(ls => ls.level === pet.level).forEach(ls => {
                const moveData = allSkills.find(skill => skill.id === ls.move) || getMoveByLevel(pet.type, ls.level);
                if (moveData) {
                  const offered = offerMoveToPet(pet, moveData);
                  Object.assign(pet, offered.pet);
                }
              });
            }

            Object.assign(pet, refreshPetEvolution(pet, POKEDEX, { timePhase, weather }));
            msg = pet.canEvolve
              ? `🍬 ${pet.name} 升到了 Lv.${pet.level}！（✨可以进化了）`
              : `🍬 ${pet.name} 升级了！Lv.${oldLv} → Lv.${pet.level}！`;

            consumed = true;
            nextInventory = { ...nextInventory, [item.id]: nextInventory[item.id] - 1 };
        } else {
            if (!pet.evs) pet.evs = {};
            pet.evs[item.stat] = Math.max(0, Number(pet.evs[item.stat]) || 0);
            const oldMaxHp = item.stat === 'hp' || item.stat === 'maxHp' ? getStats(pet).maxHp : null;
            const totalEv = Object.values(pet.evs).reduce((s, v) => s + Math.max(0, Number(v) || 0), 0);
            const critRoom = item.stat === 'crit' ? Math.max(0, MAX_BATTLE_CRIT_CHANCE - getStats(pet).crit) : Infinity;
            const maxAdd = Math.min(item.val, 252 - pet.evs[item.stat], 510 - totalEv, critRoom);
            if (maxAdd <= 0) { showMapToast('ℹ️', '提示', '该精灵的努力值已经达到上限了！', 2000); return; }
            pet.evs[item.stat] += maxAdd;
            if (item.stat === 'hp' || item.stat === 'maxHp') {
              const newMaxHp = getStats(pet).maxHp;
              pet.currentHp = Math.min(newMaxHp, pet.currentHp + Math.max(0, newMaxHp - oldMaxHp));
            }
            consumed = true;
            msg = `${pet.name} 的能力提升了！`;
            nextInventory = { ...nextInventory, [item.id]: nextInventory[item.id] - 1 };
        }
        
        // ▼▼▼ [新增] 增强剂也增加亲密度 ▼▼▼
        if(consumed) {
            pet.intimacy = Math.min(255, (pet.intimacy || 0) + 3); // 贵重物品加更多
            const refreshedPet = refreshPetEvolution(pet, POKEDEX, { timePhase, weather });
            newParty[petIdx] = refreshedPet;
            msg += ` (亲密度 +3)`;
            if (!evolutionReadyBeforeUse && refreshedPet.canEvolve && !msg.includes('可以进化')) {
              msg += '（✨可以进化了）';
            }
        }
        // ▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲▲
    }

    if (consumed) {
        const refreshedPet = refreshPetEvolution(newParty[petIdx], POKEDEX, { timePhase, weather });
        newParty[petIdx] = refreshedPet;
        if (!evolutionReadyBeforeUse && refreshedPet?.canEvolve && !msg.includes('可以进化')) {
          msg += '（✨可以进化了）';
        }
        partyRef.current = newParty;
        inventoryRef.current = nextInventory;
        flushSync(() => { setParty(newParty); setInventory(nextInventory); });
        const levelsGained = refreshedPet.level - currentParty[petIdx].level;
        if (actionItem.category === 'growth' && levelsGained > 0 && marriageRef.current?.pendingPropose) {
          updateQuestProgress(marriageRef.current.pendingPropose, 'level_up', levelsGained);
        }
        showMapToast('✅', '使用成功', msg, 2000);

        if (usingItem.category === 'growth' && refreshedPet.pendingLearnMove) {
          setUsingItem(null);
          setLearningPetIdx(petIdx);
          setPendingMove(refreshedPet.pendingLearnMove);
          setView('move_forget');
          return;
        }
        
        let currentCount = 0;
        if (usingItem.category === 'meds') {
            currentCount = (nextInventory.meds?.[usingItem.id] || 0);
        }
        else if (usingItem.category === 'berry') {
            currentCount = normalizeBerriesInventory(nextInventory.berries)[usingItem.id] || 0;
        }
        else if (usingItem.category === 'tm') currentCount = (nextInventory.tms?.[usingItem.id] || 0);
        else if (usingItem.category === 'stone') currentCount = ((nextInventory.stones || {})[usingItem.id] || 0);
        else if (usingItem.category === 'growth') currentCount = (nextInventory[usingItem.id] || 0);
        
        if (currentCount <= 0) {
            setUsingItem(null);
            setView('bag');
        }
    }
    } finally {
      window.setTimeout(() => inventoryActionLocksRef.current.delete(lockKey), 0);
    }
  };

  // ==========================================
  // [新增] 生成随机技能装备
  // ==========================================
  const createUniqueEquip = (baseId, customBase = null) => {
    const base = customBase || RANDOM_EQUIP_DB.find(i => i.id === baseId);
    if (!base) return null;

    const validSkills = allSkills.filter(s => s.category === 'status' || s.p >= 40);
    const randomSkill = _.sample(validSkills);
    if (!randomSkill) return null;

    return {
      ...base,
      type: base.stat || base.type,
      val: base.val || 0,
      uid: Date.now() + Math.random(),
      isUnique: true,
      extraSkill: randomSkill,
      displayName: `[${randomSkill.name}] ${base.name}`
    };
  };

  // ==========================================
  // [前置] getMoveByLevel 已提取至 utils/petFactory.js
  // ==========================================

  // ==========================================
  // [前置] 伴侣加成 (createPet 依赖)
  // ==========================================
  const getSpouseBonuses = () => {
    return getSpouseBonusesForState(marriageRef.current || marriage);
  };

  const consumeSpouseReroll = (cost) => {
    if (cost !== 0) return;
    const current = marriageRef.current;
    const today = getLocalDateStr();
    const next = { ...current, freeRerollDate: today, freeRerollsUsed: (current.freeRerollDate === today ? current.freeRerollsUsed || 0 : 0) + 1 };
    marriageRef.current = next;
    setMarriage(next);
  };

  // ==========================================
  // [核心修复] 创建精灵 - 委托给 utils/petFactory.js
  // ==========================================
  function createPet(dexId, level, isBoss = false, forceShiny = false, options = {}) {
    return createPetRaw(dexId, level, isBoss, forceShiny, {
      ...options,
      spouseBonuses: getSpouseBonuses(),
      getStatsForPet: (pet) => getStats(pet),
    });
  }

// ... 在其他的 useEffect 附近添加 ...

// 🎵 [修复] 全局交互监听：解决浏览器禁止自动播放的问题
useEffect(() => {
  const unlockAudioContext = () => {
    if (audioRef.current) {
      // 尝试恢复播放（如果处于暂停状态且有源）
      if (audioRef.current.paused && audioRef.current.src) {
        audioRef.current.play().catch(e => { if (process.env.NODE_ENV === 'development') console.log("等待音频加载...", e); });
      }
    }
    // 只要用户交互过一次，就移除监听，避免性能浪费
    // 注意：如果你希望每次点击都尝试恢复，可以不移除，但通常一次就够了
    // window.removeEventListener('click', unlockAudioContext);
    // window.removeEventListener('keydown', unlockAudioContext);
  };

  window.addEventListener('click', unlockAudioContext);
  window.addEventListener('keydown', unlockAudioContext);

  return () => {
    window.removeEventListener('click', unlockAudioContext);
    window.removeEventListener('keydown', unlockAudioContext);
  };
}, []);

