  const buildSavePayloadRef = useRef(buildSavePayload);
  buildSavePayloadRef.current = buildSavePayload;

  const persistSave = (silent = false, immediate = false) => {
    const doSave = () => {
      try {
        const saveResult = writeGameSave(SAVE_KEY, JSON.stringify(buildSavePayloadRef.current()));
        if (!saveResult.ok) {
          const details = saveResult.errors?.map(item => item.message).filter(Boolean).join('; ');
          const saveError = new Error(details || 'No save backend accepted the data');
          if (/quota|storage.*full|空间不足/i.test(details || '')) saveError.name = 'QuotaExceededError';
          throw saveError;
        }
        if (saveResult.degraded) console.warn('存档保存使用降级后端', saveResult.warnings);
        setHasSave(true);
        if (!silent) { setAutoSaveMsg('存档保存成功'); setTimeout(() => setAutoSaveMsg(''), 2000); }
        return true;
      } catch (e) {
        console.error("存档保存失败", e);
        if (e?.name === 'QuotaExceededError' || e?.code === 22) {
          showMapToast('⚠️', '存储空间不足', '浏览器存储已满，请导出存档或清理数据以防丢档！', 6000);
          setAutoSaveMsg('⚠️ 存储空间不足！请及时导出存档');
          setTimeout(() => setAutoSaveMsg(''), 8000);
        } else if (!silent) {
          setAutoSaveMsg('存档保存失败！'); setTimeout(() => setAutoSaveMsg(''), 3000);
        }
        return false;
      }
    };
    if (!immediate && silent && typeof requestIdleCallback === 'function') {
      requestIdleCallback(() => doSave(), { timeout: 3000 });
      return true;
    }
    return doSave();
  };

  const [saving, setSaving] = useState(false);
