  const [activityCenter, setActivityCenter] = useState(false);
  const [expPicking, setExpPicking] = useState(null);
  const [expSelectedPets, setExpSelectedPets] = useState([]);
  const [mineTab, setMineTab] = useState('dig');
  const [collectingExp, setCollectingExp] = useState(false);

  // ==========================================
  // 成就系统 - 核心函数
  // ==========================================
  const ACH_STAT_REPLACE_KEYS = useMemo(() => new Set([
    'clearedDungeonList',
    'clearedT4List',
    'uniqueDungeonsCleared',
    'tier4DungeonsCleared',
    'usedStonesList',
    'uniqueStonesUsed',
  ]), []);

  const updateAchStat = useCallback((updates) => {
    if (ultraTrialActiveRef.current) return;
    const prev = achStatsRef.current || {};
    const next = { ...prev };
    for (const [k, v] of Object.entries(updates)) {
        if (typeof v === 'function') next[k] = v(prev[k]);
        else if (typeof v === 'boolean') next[k] = v;
        else if (ACH_STAT_REPLACE_KEYS.has(k)) next[k] = Array.isArray(v) ? [...v] : v;
        else if (Array.isArray(v)) next[k] = [...v];
        else if (v && typeof v === 'object') next[k] = { ...v };
        else if (k.startsWith('max')) next[k] = Math.max(Number(prev[k]) || 0, Number(v) || 0);
        else if (typeof v === 'number') next[k] = (Number(prev[k]) || 0) + v;
        else next[k] = v;
    }
    achStatsRef.current = next;
    setAchStats(next);
  }, [ACH_STAT_REPLACE_KEYS]);

  const recordDungeonCompletion = (dungeonId) => {
    if (!dungeonId) return false;
    const stats = achStatsRef.current || {};
    const clearedDungeonList = [...new Set([...(stats.clearedDungeonList || []), dungeonId])];
    const tier4Ids = ['infinity_castle', 'safari_zone', 'extreme_trial', 'treasure_maze', 'ragnarok'];
    const clearedT4List = tier4Ids.includes(dungeonId)
      ? [...new Set([...(stats.clearedT4List || []), dungeonId])]
      : [...(stats.clearedT4List || [])];
    updateAchStat({
      dungeonsCleared: 1,
      uniqueDungeonsCleared: clearedDungeonList.length,
      clearedDungeonList,
      tier4DungeonsCleared: clearedT4List.length,
      clearedT4List,
    });
    return true;
  };

  const formatAchievementReward = (reward) => {
    if (!reward) return [];
    const parts = [];
    if (reward.title) parts.push(`称号 ${reward.title}`);
    if (reward.item) parts.push(`${reward.itemLabel || reward.item} x${reward.itemCount || 1}`);
    (reward.items || []).forEach(item => parts.push(`${item.label || item.id} x${item.count || 1}`));
    return parts;
  };

  const grantAchievementRewardItem = (item) => {
    if (!item?.id || !item?.count) return;
    const count = Math.max(1, item.count || 1);
    if (item.type === 'ball') {
      setInventory(prev => ({ ...prev, balls: { ...(prev.balls || {}), [item.id]: ((prev.balls || {})[item.id] || 0) + count } }));
      return;
    }
    if (item.type === 'candy' && (item.id === 'exp_candy' || item.id === 'max_candy')) {
      setInventory(prev => ({ ...prev, [item.id]: (prev[item.id] || 0) + count }));
      return;
    }
    if (item.type === 'system' && item.id === 'factionTokens') {
      setKingdomWar(prev => ({ ...prev, factionTokens: (prev.factionTokens || 0) + count }));
      return;
    }
    if (item.type === 'system' && item.id === 'sectContribution') {
      setSectPlayer(prev => ({ ...prev, sectResources: { ...(prev.sectResources || {}), contribution: (prev.sectResources?.contribution || 0) + count } }));
      return;
    }
    if (item.type === 'system' && item.id === 'gangContribution') {
      setGang(prev => ({ ...prev, contribution: (prev.contribution || 0) + count }));
      return;
    }
    if (item.type === 'system' && item.id === 'sanctuaryEssence') {
      setSanctuaryState(prev => ({ ...prev, ecoEssence: (prev.ecoEssence || 0) + count }));
      return;
    }
    if (item.type === 'system' && item.id === 'chakraOre') {
      setInventory(prev => ({ ...prev, misc: { ...(prev.misc || {}), chakra_ore: ((prev.misc || {}).chakra_ore || 0) + count } }));
      return;
    }
    if (item.type === 'item') {
      setInventory(prev => ({ ...prev, [item.id]: (prev[item.id] || 0) + count }));
      return;
    }
    const cat = item.itemCat || item.cat || 'misc';
    setInventory(prev => {
      const sub = prev[cat] || {};
      return { ...prev, [cat]: { ...sub, [item.id]: (sub[item.id] || 0) + count } };
    });
  };

  const checkAchievements = useCallback((statsOverride) => {
    const stats = statsOverride || achStats;
    const newUnlocks = [];
    const unlockedIds = new Set(unlockedAchsRef.current || []);
    ACHIEVEMENTS.forEach(ach => {
      if (unlockedIds.has(ach.id)) return;
      try {
        if (ach.check(stats)) {
          newUnlocks.push(ach);
          unlockedIds.add(ach.id);
        }
      } catch (e) { console.warn('Achievement check failed:', ach.id, e); }
    });
    if (newUnlocks.length > 0) {
      const newIds = newUnlocks.map(a => a.id);
      unlockedAchsRef.current = [...unlockedIds];
      setUnlockedAchs(unlockedAchsRef.current);
      newUnlocks.forEach(ach => {
        if (ach.reward) {
          if (ach.reward.title) unlockTitle(ach.reward.title);
          if (ach.reward.item) {
            grantAchievementRewardItem({
              type: ach.reward.itemCat === 'balls' ? 'ball' : 'item',
              id: ach.reward.item,
              count: ach.reward.itemCount || 1,
              cat: ach.reward.itemCat,
              label: ach.reward.itemLabel,
            });
          }
          (ach.reward.items || []).forEach(grantAchievementRewardItem);
        }
      });
      achTimersRef.current.forEach(t => clearTimeout(t));
      achTimersRef.current = [];
      setAchNotification(newUnlocks[0]);
      for (let idx = 1; idx < newUnlocks.length; idx++) {
        achTimersRef.current.push(setTimeout(() => setAchNotification(newUnlocks[idx]), 2500 * idx));
      }
      achTimersRef.current.push(setTimeout(() => setAchNotification(null), 2500 * newUnlocks.length + 500));
    }
    return () => { achTimersRef.current.forEach(t => clearTimeout(t)); achTimersRef.current = []; };
  }, [achStats]);

  useEffect(() => {
    checkAchievements();
  }, [achStats, unlockedAchs.length]); // eslint-disable-line

  const syncAchStats = useCallback(() => {
    setAchStats(prev => {
      const next = { ...prev };
      next.dexCount = caughtDex.length;
      // totalCaught 仅由 capture 事件递增，不用图鉴长度覆盖
      next.badgeCount = badges.length;
      next.leagueWins = leagueWins;
      next.sectChiefsDefeated = Math.max((sectPlayer?.sectChiefTrials || []).length, (sectPlayer?.sectTitles || []).length);
      next.sectPlayerRank = sectPlayer?.sectRank || 0;
      next.sectJoined = sectPlayer?.playerSect ? 1 : 0;
      next.sectChiefTrials = (sectPlayer?.sectChiefTrials || []).length;
      next.sectRealmsCleared = (fusionState?.sectRealmsCleared || []).length;
      next.sectJianghuEvents = (sectPlayer?.sectEventLog || []).length;
      next.uniqueFruits = [...new Set(fruitInventory || [])].length;
      const allChallengeIds = new Set([...CHALLENGES, ...ATTR_CHALLENGES, ...DOUBLE_CHALLENGES, ...JJK_CHALLENGES].map(c => c.id));
      next.challengesCompleted = (completedChallenges || []).filter(id => allChallengeIds.has(id)).length;
      next.achievementCount = unlockedAchs.length;
      const allPets = [...(party || []), ...(box || [])];
      next.maxPetLevel = Math.max(0, ...allPets.map(p => p?.level || 0));
      if (party && party.length > 0) {
        next.starterLevel = party[0]?.level || 0;
      }
      const team = party || [];
      next.eliteTeamReady = team.length >= 6 && team.every(p => (p?.level || 0) >= 50);
      next.fullLv100Team = team.length >= 6 && team.every(p => (p?.level || 0) >= 100);
      const types = new Set();
      const typesAll = new Set();
      (caughtDex || []).forEach(id => {
        const p = POKEDEX.find(pk => pk.id === id);
        if (p) {
          if (p.type) { types.add(p.type); typesAll.add(p.type); }
          if (p.type2) { types.add(p.type2); typesAll.add(p.type2); }
        }
      });
      next.typesCollected = types.size;
      const houseTier = {'tent':1,'cabin':2,'house':3,'mansion':4,'castle':5,'beach_house':5,'garden_villa':5,'cloud_loft':6,'crystal_palace':7,'world_tree':8};
      next.houseLevel = houseTier[housing?.currentHouse || housing?.houseType || 'tent'] || 1;
      next.furnitureCount = (housing?.furniture || []).filter(f => f?.placed).length;
      let hsScore = calcHouseScore ? calcHouseScore((housing?.furniture || []).filter(f => f?.placed), getSpouseBonuses().homeScore || 0) : 0;
      const treasures = housing?.treasures || [];
      hsScore += treasures.reduce((s, tid) => {
        for (const col of TREASURE_COLLECTIONS) {
          const item = col.items.find(i => i.id === tid);
          if (item) return s + item.score;
        }
        return s;
      }, 0);
      const hsTierObj = getHousingScoreTier ? getHousingScoreTier(hsScore) : null;
      next.housingScoreTier = hsTierObj ? Math.max(0, HOUSING_SCORE_TIERS.indexOf(hsTierObj)) : 0;
      next.mapsVisited = Object.keys(mapProgress || {}).length;
      const explorableMapIds = MAPS.filter(m => !m.noEncounter).map(m => String(m.id));
      const progressedMapIds = new Set(Object.keys(mapProgress || {}));
      next.allMapsUnlocked = explorableMapIds.length > 0 && explorableMapIds.every(id => progressedMapIds.has(id));
      const mapCaughtSpecies = prev.mapCaughtSpecies || {};
      next.worldTourComplete = explorableMapIds.length > 0
        && explorableMapIds.every(id => new Set(mapCaughtSpecies[id] || []).size >= 5) ? 1 : 0;
      // 队伍属性多样性
      const partyTypes = new Set((party || []).map(p => p?.type).filter(Boolean));
      const partyTypesAll = new Set();
      (party || []).forEach(p => {
        if (p?.type) partyTypesAll.add(p.type);
        if (p?.type2 || p?.secondaryType) partyTypesAll.add(p.type2 || p.secondaryType);
      });
      next.partyTypeDiv = partyTypes.size;
      next.uniquePartyTypes = partyTypesAll.size;
      // 双属性/宇宙/音波/时空/混沌收藏统计
      let dualCount = 0, cosmicCount = 0, soundCount = 0, timeCount = 0, chaosCount = 0;
      (caughtDex || []).forEach(id => {
        const pk = POKEDEX.find(p => p.id === id);
        if (!pk) return;
        const t2 = pk.secondaryType || pk.type2;
        if (pk.type && t2) dualCount++;
        if (pk.type === 'COSMIC' || t2 === 'COSMIC') cosmicCount++;
        if (pk.type === 'SOUND' || t2 === 'SOUND') soundCount++;
        if (pk.type === 'TIME' || t2 === 'TIME') timeCount++;
        if (pk.type === 'CHAOS' || t2 === 'CHAOS') chaosCount++;
      });
      next.dualTypeCaught = dualCount;
      next.cosmicCaught = cosmicCount;
      next.soundCaught = soundCount;
      next.timeCaught = timeCount;
      next.chaosCaught = chaosCount;
      // 隐藏成就：全队闪光
      next.fullShinyTeam = (party || []).length >= 6 && (party || []).every(p => p?.isShiny || p?.isFusedShiny);
      // 队伍门派多样性
      const partySects = new Set((party || []).map(p => p?.sectId).filter(Boolean));
      next.partySectDiv = partySects.size;
      // 50级以上精灵数量
      const allP = [...(party || []), ...(box || [])];
      next.lv50PetCount = allP.filter(p => (p?.level || 0) >= 50).length;
      if (gang?.gangId) {
        const rank = getGangRank(gang.contribution, gang.isOwner);
        next.gangRank = rank ? GANG_RANKS.indexOf(rank) : -1;
      } else {
        next.gangRank = -1;
      }
      next.maxIntimacy = Math.max(0, ...allPets.map(p => p?.intimacy || 0));
      next.maxSkillCount = Math.max(0, ...allPets.map(p => (p?.moves || []).length));
      if (marriage?.spouse) next.marriageComplete = 1;
      if (kingdomWar?.faction) {
        next.kwJoined = true;
        const rankIdx = MILITARY_RANKS.findIndex(r => r.id === (kingdomWar.militaryRank || 'civilian'));
        next.kwRankIdx = rankIdx >= 0 ? rankIdx : 0;
        next.kwFactionTerritories = getFactionTerritoryCount(kingdomWar.faction, kingdomWar.territories || {});
        const rg = kingdomWar.recruitedGenerals || [];
        next.kwGenerals = rg.length;
        next.kwSSRGenerals = rg.filter(g => g.rarity === 'SSR').length;
        next.kwGenFactions = new Set(rg.map(g => g.warCamp).filter(f => ['wei', 'shu', 'wu', 'jin'].includes(f))).size;
        next.kwGenDexTotal = (kingdomWar.collectedGeneralIds || []).length;
        next.kwContribution = kingdomWar.lifetimeContribution || kingdomWar.warContribution || 0;
        next.kwCampaignsCleared = (kingdomWar.completedCampaigns || []).length;
        const chb = kingdomWar.completedHistoricalBattles || [];
        next.hbCompleted = chb.length;
        next.hbEra1 = chb.filter(id => id.startsWith('hb_') && HISTORICAL_BATTLES.find(b => b.id === id && b.era === 'era1')).length;
        next.hbEra2 = chb.filter(id => id.startsWith('hb_') && HISTORICAL_BATTLES.find(b => b.id === id && b.era === 'era2')).length;
        next.hbEra3 = chb.filter(id => id.startsWith('hb_') && HISTORICAL_BATTLES.find(b => b.id === id && b.era === 'era3')).length;
        next.hbEra4 = chb.filter(id => id.startsWith('hb_') && HISTORICAL_BATTLES.find(b => b.id === id && b.era === 'era4')).length;
      } else {
        next.kwJoined = false;
        next.kwRankIdx = 0;
        next.kwFactionTerritories = 0;
        next.kwGenerals = 0;
        next.kwSSRGenerals = 0;
      }
      if (narutoState) {
        next.bijuuCount = (narutoState.bijuuCollected || []).length;
        next.examHighScore = narutoState.examHighScore || 0;
        next.chuninExams = narutoState.examsCompleted || 0;
        next.narutoChalsCompleted = (narutoState.completedChallenges || []).length;
        const mst = narutoState.jutsuMastery || {};
        next.jutsuMasteredCount = Object.values(mst).filter(v => v >= 25).length;
        next.jutsuSkilledCount = Object.values(mst).filter(v => v >= 25).length;
        next.jutsuOugiCount = Object.values(mst).filter(v => v >= 100).length;
      }
      next.raceWins = raceState?.totalWins || prev.raceWins || 0;
      next.petsAwakened = Math.max(prev.petsAwakened || 0, allP.filter(p => p?.awakened).length);
      next.relicsCollected = Math.max(prev.relicsCollected || 0, (relics?.owned || []).length);
      next.guardianScoreTotal = Math.max(prev.guardianScoreTotal || 0, guardianScore || 0);
      if (kingdomWar?.faction) {
        const chb = kingdomWar.completedHistoricalBattles || [];
        next.hbCompleted = chb.length;
      }
      achStatsRef.current = next;
      return next;
    });
  }, [caughtDex, badges, leagueWins, sectTitles, fruitInventory, completedChallenges, unlockedAchs, party, box, housing, mapProgress, gang, marriage, kingdomWar, narutoState, raceState, relics, guardianScore, sectPlayer, fusionState]);

  useEffect(() => {
    syncAchStats();
  }, [caughtDex, badges, leagueWins, sectTitles, fruitInventory, completedChallenges, party, box, housing, mapProgress, unlockedAchs, gang, marriage, kingdomWar, narutoState, raceState, relics, guardianScore, sectPlayer, fusionState]);

  useEffect(() => {
    if (caughtDex.length > 0) checkDexTitles(caughtDex.length);
  }, [caughtDex]);

    // [新增] 解锁称号通用函数
  const unlockTitle = (title) => {
      if (title && !unlockedTitlesRef.current.includes(title)) {
          unlockedTitlesRef.current = [...unlockedTitlesRef.current, title];
          setUnlockedTitles(unlockedTitlesRef.current);
          addGlobalLog(`🏆 获得新称号：[${title}]`);
          showMapToast('🏆', '获得新称号！', `【${title}】- 可在训练家卡片中佩戴`, 4000);
      }
  };

  // [新增] 检查图鉴类称号 (每次捕获/进化后调用)
  const checkDexTitles = (currentCount) => {
      if (currentCount >= 10) unlockTitle('初出茅庐');
      if (currentCount >= 30) unlockTitle('见闻者');
      if (currentCount >= 50) unlockTitle('新手收藏家');
      if (currentCount >= 100) unlockTitle('图鉴达人');
      if (currentCount >= 150) unlockTitle('探索先锋');
      if (currentCount >= 250) unlockTitle('博学大师');
      if (currentCount >= 350) unlockTitle('百科行者');
      if (currentCount >= 450) unlockTitle('全图鉴霸主');
      if (currentCount >= 550) unlockTitle('万物通晓');
      if (currentCount >= 700) unlockTitle('传说收藏家');
      if (currentCount >= 800) unlockTitle('图鉴完成者');
      if (currentCount >= 899) unlockTitle('终极图鉴大师');
  };

  const handleStartGame = () => {
    if (hasSave && party.length > 0) {
      setView('world_map');
    } else {
      setView('name_input');
    }
  };
    // 打开装备选择弹窗
  const openEquipModal = (petIdx, slotIdx) => {
    setTargetEquipSlot({ petIdx, slotIdx });
    setEquipModalOpen(true);
  };

    const handleEquipAccessory = (accOrId) => {
    if (equipmentActionLockRef.current) return;
    equipmentActionLockRef.current = true;
    try {
    const { petIdx, slotIdx } = targetEquipSlot;
    const currentParty = partyRef.current || [];
    const newParty = [...currentParty];
    const sourcePet = newParty[petIdx];
    const pet = sourcePet ? { ...sourcePet, equips: [...(sourcePet.equips || [null, null])] } : null;
    if (!pet) { showMapToast('❌', '提示', '精灵不存在！', 1500); return; }
    newParty[petIdx] = pet;

    const otherSlot = slotIdx === 0 ? 1 : 0;
    const otherEquip = pet.equips[otherSlot];
    if (typeof accOrId === 'string' && otherEquip === accOrId) {
      showMapToast('❌', '装备失败', '不能装备两个相同的饰品', 1500); return;
    }
    if (typeof accOrId === 'object' && typeof otherEquip === 'object' && accOrId.uid === otherEquip?.uid) {
      showMapToast('❌', '装备失败', '不能装备两个相同的饰品', 1500); return;
    }

    const oldEquip = pet.equips[slotIdx];
    const newAccessories = [...accessoriesRef.current];

    // 1. 先从背包移除新装备
    let accIndex = -1;
    if (typeof accOrId === 'object') {
        accIndex = newAccessories.findIndex(a => a.uid === accOrId.uid);
    } else {
        accIndex = newAccessories.indexOf(accOrId);
    }
    
    if (accIndex > -1) {
        newAccessories.splice(accIndex, 1);
    } else {
        showMapToast('❌', '装备失败', '背包中未找到该装备', 1500); return;
    }

    // 2. 再卸下旧装备放回背包
    if (oldEquip) {
        newAccessories.push(oldEquip);
    }

    pet.equips[slotIdx] = accOrId;

    partyRef.current = newParty;
    accessoriesRef.current = newAccessories;
    flushSync(() => { setParty(newParty); setAccessories(newAccessories); });
    setEquipModalOpen(false);
    } finally {
      window.setTimeout(() => { equipmentActionLockRef.current = false; }, 0);
    }
  };


  // 卸下当前饰品
  const handleUnequip = () => {
    if (equipmentActionLockRef.current) return;
    equipmentActionLockRef.current = true;
    try {
    const { petIdx, slotIdx } = targetEquipSlot;
    const newParty = [...(partyRef.current || [])];
    const sourcePet = newParty[petIdx];
    const pet = sourcePet ? { ...sourcePet, equips: [...(sourcePet.equips || [null, null])] } : null;
    if (!pet) return;
    newParty[petIdx] = pet;

    if (!pet.equips || !pet.equips[slotIdx]) {
        setEquipModalOpen(false);
        return;
    }

    const oldAccId = pet.equips[slotIdx];
    
    // 放回背包
    const newAccessories = [...accessoriesRef.current, oldAccId];
    // 清空槽位
    pet.equips[slotIdx] = null;

    partyRef.current = newParty;
    accessoriesRef.current = newAccessories;
    flushSync(() => { setParty(newParty); setAccessories(newAccessories); });
    setEquipModalOpen(false);
    } finally {
      window.setTimeout(() => { equipmentActionLockRef.current = false; }, 0);
    }
  };

    // ==========================================
  // [修改] 核心融合逻辑 
  // 1. 种族值混合: Min*0.9 ~ Max*1.1 之间随机
  // 2. 等级: (父+母)/2
  // 3. IV: 随机生成
  // ==========================================
  // --- 融合逻辑处理函数 (使用完整混合算法) ---
  const getFusionCost = () => {
    const badgeCount = badges?.length || 0;
    if (badgeCount >= 8) return 30000;
    if (badgeCount >= 5) return 15000;
    return 5000;
  };
  const handleFusion = () => {
    if (!fusionParent || !fusionChild || fusionActionLockRef.current) return;
    fusionActionLockRef.current = true;
    try {
    const fusionCost = getFusionCost();
    if (goldRef.current < fusionCost) { showMapToast('💰', '金币不足', `融合需要 ${fusionCost} 金币`, 1500); return; }

    const currentParty = partyRef.current || [];
    const parentUid = fusionParent.uid || fusionParent.id;
    const childUid = fusionChild.uid || fusionChild.id;
    const p1 = currentParty.find(p => (p.uid || p.id) === parentUid);
    const p2 = currentParty.find(p => (p.uid || p.id) === childUid);
    if (!p1 || !p2) { showMapToast('⚠️', '融合失败', '素材已不在当前队伍中', 2000); return; }
    if (p1.uid === p2.uid) { showMapToast('⚠️','融合失败','不能融合同一只精灵',1500); return; }
    if (!canUseAsFusionMaterial(p1) || !canUseAsFusionMaterial(p2)) {
      showMapToast('⚠️', '融合失败', '融合体不能再次作为融合素材', 2000);
      return;
    }
    const currentPartyUids = new Set(currentParty.map(p => p.uid || p.id));
    if (!currentPartyUids.has(p1.uid || p1.id) || !currentPartyUids.has(p2.uid || p2.id)) {
      showMapToast('⚠️', '融合失败', '素材已不在当前队伍中', 2000);
      return;
    }

    const baseParent = Math.random() < 0.5 ? p1 : p2;
    const otherParent = baseParent.uid === p1.uid ? p2 : p1;
    
    const isFusedShiny = Math.random() < getFusionShinyChance(p1, p2);

    const isDualType = Math.random() < 0.2;
    const dexForBase = POKEDEX.find(d => d.id === baseParent.id) || POKEDEX[0];
    let fusionGrantedSecondary = null;
    if (isDualType && otherParent.type !== baseParent.type) {
        fusionGrantedSecondary = otherParent.type;
    }
    const secondaryType =
        fusionGrantedSecondary ?? baseParent.secondaryType ?? dexForBase.type2 ?? null;

    const getBase = (pet) => pet.customBaseStats || (POKEDEX.find(d=>d.id===pet.id) || POKEDEX[0]);
    const b1 = getBase(p1);
    const b2 = getBase(p2);
    const mixStat = (key) => {
        const v1 = b1[key] || (key.includes('atk') ? b1.atk : b1.def) || 50;
        const v2 = b2[key] || (key.includes('atk') ? b2.atk : b2.def) || 50;
        const min = Math.min(v1, v2) * 0.9;
        const max = Math.max(v1, v2) * 1.1;
        return Math.floor(min + Math.random() * (max - min));
    };
    const newBaseStats = {
        hp: mixStat('hp'), p_atk: mixStat('p_atk'), p_def: mixStat('p_def'),
        s_atk: mixStat('s_atk'), s_def: mixStat('s_def'), spd: mixStat('spd'),
        crit: Math.max(b1.crit||5, b2.crit||5)
    };

    const poolMoves2 = [...(p1.moves||[]), ...(p2.moves||[])];
    const uniqueMoves2 = _.uniqBy(poolMoves2, 'name');
    const atkMoves = uniqueMoves2.filter(m => m.p > 0);
    const statusMoves = uniqueMoves2.filter(m => !m.p || m.p === 0);
    let finalMoves2;
    if (atkMoves.length >= 2) {
      const picked = _.sampleSize(atkMoves, 2);
      const rest = _.sampleSize(statusMoves.length > 0 ? [...statusMoves, ...atkMoves.filter(m => !picked.includes(m))] : atkMoves.filter(m => !picked.includes(m)), 2);
      finalMoves2 = [...picked, ...rest].slice(0, 4);
    } else {
      finalMoves2 = _.sampleSize(uniqueMoves2, 4);
    }
    if (finalMoves2.length === 0) {
      const fallbackSkill2 = allSkills.find(s => s.t === baseParent.type && s.p > 0) || allSkills[0] || { name: '撞击', t: 'NORMAL', p: 40, pp: 35, maxPP: 35, desc: '基础物理攻击' };
      finalMoves2 = [{ ...fallbackSkill2, pp: fallbackSkill2.maxPP || 15 }];
    }

    const avgLevel = Math.min(100, Math.floor((p1.level + p2.level) / 2));
    const natureData = NATURE_DB[baseParent.nature || 'docile'];
    const newNextExp = calcNextExp(avgLevel, natureData?.exp || 1.0);

    const randIV = () => Math.floor(Math.random() * 32);
    const fusionCharm = Math.min(100, (TYPE_CHARM_BASE[baseParent.type] || 30) + Math.floor(Math.random() * 21));
    let newPet = {
        ...baseParent,
        uid: Date.now() + Math.random(),
        name: `融合·${baseParent.name}`,
        isFusion: true,
        level: avgLevel, exp: 0, nextExp: newNextExp,
        moves: finalMoves2.map(m => ({ ...m, pp: m.maxPP || m.pp || 15, maxPP: m.maxPP || m.pp || 15 })),
        customBaseStats: newBaseStats,
        secondaryType: secondaryType,
        isFusedShiny: false,
        isShiny: false,
        charm: fusionCharm,
        charmRank: getCharmRank(fusionCharm),
        equips: [null, null],
        ivs: { hp: randIV(), p_atk: randIV(), p_def: randIV(),
               s_atk: randIV(), s_def: randIV(), spd: randIV(), crit: Math.floor(Math.random()*10) },
        evs: {},
        canEvolve: false,
        evo: null,
    };
    if (isFusedShiny) {
      newPet = { ...promotePetToShiny(newPet), isFusedShiny: true };
    }

    const finalStats = getStats(newPet);
    newPet.currentHp = finalStats.maxHp;

    goldRef.current -= fusionCost;
    setGold(goldRef.current);
    updateAchStat({ totalGoldSpent: fusionCost });
    const returnedEquips = [];
    [p1, p2].forEach(parent => {
      if (parent.equips) {
        parent.equips.forEach(eq => { if (eq) returnedEquips.push(eq); });
      }
    });
    if (returnedEquips.length > 0) {
      accessoriesRef.current = [...accessoriesRef.current, ...returnedEquips];
      setAccessories(accessoriesRef.current);
    }
    const newParty = currentParty.filter(p => {
      const pUid = p.uid || p.id;
      return pUid !== parentUid && pUid !== childUid;
    });
    newParty.push(newPet);
    partyRef.current = newParty;
    setParty(newParty);
    
    setFusionParent(null);
    setFusionChild(null);

    let desc = `Lv.${newPet.level} ${newPet.name}`;
    if (isFusedShiny) desc += ' ✨异色闪光！';
    if (fusionGrantedSecondary) desc += ` ⚡双属性：${TYPES[baseParent.type]?.name || baseParent.type}/${TYPES[fusionGrantedSecondary]?.name || fusionGrantedSecondary}`;
    showMapToast('🧬', '融合成功', desc, 3500);
    updateAchStat({ totalFusions: 1 });
    } finally {
      window.setTimeout(() => { fusionActionLockRef.current = false; }, 0);
    }
  };

    // ==========================================
